SCRIPT_DIR = Path(__file__).resolve().parent
RUNTIME_LOG_FILE_NAME = "RE6_ARC_TOOL_RUNTIME.log"
RUNTIME_LOG_PATH = SCRIPT_DIR / RUNTIME_LOG_FILE_NAME
_RUNTIME_FAULT_STREAM: Any = None


def assert_python_archive_independence() -> None:
    forbidden_token = "".join(("arc", "tool"))
    offenders: list[str] = []
    for source_path in sorted(SCRIPT_DIR.glob("*.py")):
        try:
            source_lines = source_path.read_text(encoding="utf-8-sig").splitlines()
        except Exception as exc:
            offenders.append(f"{source_path.name}: unreadable source: {exc}")
            continue
        for line_number, line in enumerate(source_lines, start=1):
            if forbidden_token in line.lower():
                offenders.append(f"{source_path.name}:{line_number}")
    if offenders:
        locations = "\n".join(f"- {item}" for item in offenders)
        raise RuntimeError(
            "Forbidden external archive dependency detected in Python source.\n"
            "This application must remain Python-owned and self-contained.\n"
            "Remove every offending reference before running it:\n"
            f"{locations}"
        )


assert_python_archive_independence()


def runtime_log(message: str) -> None:
    try:
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        with RUNTIME_LOG_PATH.open("a", encoding="utf-8", errors="replace") as handle:
            handle.write(f"[{stamp}] {message.rstrip()}\n")
    except Exception:
        pass


def format_exception_text(exc_type: Any, exc_value: Any, exc_traceback: Any) -> str:
    try:
        return "".join(traceback.format_exception(exc_type, exc_value, exc_traceback)).rstrip()
    except Exception:
        return f"{exc_type!r}: {exc_value!r}"


def install_runtime_crash_logging() -> None:
    global _RUNTIME_FAULT_STREAM
    runtime_log("=== Process Start ===")
    runtime_log(f"PID={os.getpid()} EXE={sys.executable}")
    runtime_log(f"CWD={os.getcwd()}")
    runtime_log(f"ARGV={json.dumps(sys.argv, ensure_ascii=False)}")
    try:
        _RUNTIME_FAULT_STREAM = RUNTIME_LOG_PATH.open("a", encoding="utf-8", errors="replace")
        faulthandler.enable(file=_RUNTIME_FAULT_STREAM, all_threads=True)
        runtime_log("faulthandler=enabled")
    except Exception as exc:
        runtime_log(f"faulthandler enable failed: {exc}")

    def _runtime_excepthook(exc_type: Any, exc_value: Any, exc_traceback: Any) -> None:
        runtime_log("UNHANDLED EXCEPTION BEGIN")
        runtime_log(format_exception_text(exc_type, exc_value, exc_traceback))
        runtime_log("UNHANDLED EXCEPTION END")
        try:
            sys.__excepthook__(exc_type, exc_value, exc_traceback)
        except Exception:
            pass

    sys.excepthook = _runtime_excepthook

    if hasattr(threading, "excepthook"):
        def _thread_excepthook(args: Any) -> None:
            runtime_log(f"THREAD EXCEPTION thread={getattr(args, 'thread', None)}")
            runtime_log(
                format_exception_text(
                    getattr(args, "exc_type", Exception),
                    getattr(args, "exc_value", Exception("unknown thread exception")),
                    getattr(args, "exc_traceback", None),
                )
            )
            try:
                threading.__excepthook__(args)
            except Exception:
                pass

        threading.excepthook = _thread_excepthook

    def _runtime_exit_hook() -> None:
        runtime_log("=== Process Exit ===")
        try:
            if _RUNTIME_FAULT_STREAM is not None:
                _RUNTIME_FAULT_STREAM.flush()
        except Exception:
            pass

    atexit.register(_runtime_exit_hook)


install_runtime_crash_logging()


