def github_source_blob_sha(path: Path) -> str:
    """Return the Git blob SHA used by GitHub's contents API for one file."""
    data = Path(path).read_bytes().replace(b"\r\n", b"\n")
    header = f"blob {len(data)}\0".encode("ascii")
    return hashlib.sha1(header + data).hexdigest()


def evaluate_github_update(
    source_sha: Any,
    release_tag: Any,
    *,
    local_source_sha: Any,
) -> dict[str, bool]:
    """Compare GitHub's current source and release against this local build."""
    current_source_sha = str(source_sha or "").strip().lower()
    current_local_source_sha = str(local_source_sha or "").strip().lower()
    current_release_tag = str(release_tag or "").strip()
    source_updated = bool(
        current_source_sha
        and current_local_source_sha
        and current_source_sha != current_local_source_sha
    )
    release_updated = bool(
        current_release_tag and current_release_tag != GITHUB_RELEASE_BASELINE_TAG
    )
    return {
        "source_updated": source_updated,
        "release_updated": release_updated,
        "updated": source_updated or release_updated,
    }


def fetch_github_update_info(
    *,
    opener: Callable[..., Any] | None = None,
) -> dict[str, Any]:
    """Read the current source SHA and latest Release metadata from GitHub."""
    request_opener = opener or urllib.request.urlopen

    def read_json(url: str) -> dict[str, Any]:
        request = urllib.request.Request(
            url,
            headers={
                "Accept": "application/vnd.github+json",
                "User-Agent": "RE6-ARC-Tool",
            },
        )
        with request_opener(request, timeout=GITHUB_UPDATE_TIMEOUT_SECONDS) as response:
            payload = json.loads(response.read().decode("utf-8"))
        if not isinstance(payload, dict):
            raise ValueError(f"GitHub returned an invalid JSON object for {url}.")
        return payload

    source_payload = read_json(GITHUB_SOURCE_API_URL)
    release_payload = read_json(GITHUB_RELEASE_API_URL)
    local_source_sha = github_source_blob_sha(SCRIPT_DIR / GITHUB_SOURCE_FILE_NAME)
    result = evaluate_github_update(
        source_payload.get("sha"),
        release_payload.get("tag_name"),
        local_source_sha=local_source_sha,
    )
    result.update(
        {
            "source_sha": str(source_payload.get("sha") or "").strip(),
            "local_source_sha": local_source_sha,
            "release_tag": str(release_payload.get("tag_name") or "").strip(),
            "release_url": str(release_payload.get("html_url") or GITHUB_RELEASE_URL),
        }
    )
    return result


def is_arc_txt_anchor_file(path: Path) -> bool:
    """Return whether one TXT file identifies an ARC working directory."""
    path = Path(path)
    if not path.is_file() or path.suffix.casefold() != ".txt":
        return False
    if path.name.casefold().endswith(LEGACY_ARC_TEXT_SUFFIX):
        return True
    try:
        # CODE X contracts are compact JSON-in-TXT files. Do not parse arbitrary
        # large text files while scanning a user's Explorer tree.
        if path.stat().st_size > 2 * 1024 * 1024:
            return False
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return False
    return isinstance(payload, dict) and payload.get("format") in {
        BATCH_MANIFEST_FORMAT,
        FOLDER_EXPORT_MANIFEST_FORMAT,
    }


def directory_has_arc_txt_anchor(directory: Path) -> bool:
    """An ARC directory is the directory that directly contains an anchor TXT."""
    directory = Path(directory)
    if not directory.is_dir():
        return False
    try:
        return any(
            is_arc_txt_anchor_file(item)
            for item in directory.iterdir()
            if item.is_file() and item.suffix.casefold() == ".txt"
        )
    except OSError:
        return False


def find_arc_txt_anchor_directories(root: Path) -> list[Path]:
    """Find working directories below ``root`` by their direct TXT anchors."""
    root = Path(root)
    if not root.is_dir():
        return []
    anchors: list[Path] = []
    for current_text, _directory_names, file_names in os.walk(
        root,
        topdown=True,
        followlinks=False,
    ):
        current = Path(current_text)
        try:
            if any(
                is_arc_txt_anchor_file(current / name)
                for name in file_names
                if Path(name).suffix.casefold() == ".txt"
            ):
                anchors.append(current)
        except OSError:
            continue
    return sorted(anchors, key=lambda item: str(item).casefold())


def find_nearest_arc_txt_anchor_directory(directory: Path) -> Path | None:
    """Return the closest current/parent directory with an ARC TXT anchor."""
    current = Path(directory)
    while True:
        if directory_has_arc_txt_anchor(current):
            return current
        parent = current.parent
        if parent == current:
            return None
        current = parent

