EXT_TO_TYPE_HASHES: dict[str, tuple[int, ...]] = {}
for _hash_value, _ext_value in TYPE_HASH_TO_EXT.items():
    _normalized_ext = _ext_value.lower()
    existing = list(EXT_TO_TYPE_HASHES.get(_normalized_ext, tuple()))
    existing.append(_hash_value)
    EXT_TO_TYPE_HASHES[_normalized_ext] = tuple(sorted(set(existing)))

