    def tr(self, english: str, chinese: str) -> str:
        return choose_ui_text(self.ui_language, english, chinese)

    def _github_update_title(self) -> str:
        return self.tr(
            "RE6 ARC Tool | Github Source Code Update Is Available. Click here to visit the Release page!",
            "RE6 ARC \u5de5\u5177 | \u53d1\u73b0Github \u6e90\u7801\u66f4\u65b0\uff0c\u70b9\u51fb\u6b64\u5904\u6253\u5f00Release \u7f51\u9875\uff01",
        )

    def _set_application_title(self) -> None:
        if getattr(self, "_github_update_found", False):
            title = self._github_update_title()
        else:
            title = self.tr("RE6 ARC Tool", "RE6 ARC \u5de5\u5177")
        self.root.title(title)
        titlebar_label = getattr(self, "titlebar_title_label", None)
        if titlebar_label is not None:
            titlebar_label.configure(text=title)
        update_label = getattr(self, "github_update_label", None)
        if update_label is not None and self._github_update_found:
            update_label.configure(text=title)

    def _open_github_release(self, _event: tk.Event | None = None) -> str:
        try:
            webbrowser.open(self._github_release_url)
        except Exception as exc:
            runtime_log(f"GitHub release link open failed: {exc}")
        return "break"

    def _apply_github_update_info(self, info: dict[str, Any]) -> None:
        if self._closing or not bool(info.get("updated")):
            return
        self._github_update_found = True
        self._github_release_url = str(info.get("release_url") or GITHUB_RELEASE_URL)
        self._set_application_title()
        update_frame = getattr(self, "github_update_frame", None)
        toolbar = getattr(self, "toolbar", None)
        if update_frame is not None and toolbar is not None:
            update_frame.pack(fill="x", before=toolbar)

    def _start_github_update_check(self) -> None:
        if self._closing:
            return

        def worker() -> None:
            try:
                info = fetch_github_update_info()
            except Exception as exc:
                runtime_log(f"GitHub update check failed: {exc}")
                return
            try:
                self.root.after(0, lambda result=info: self._apply_github_update_info(result))
            except Exception as exc:
                runtime_log(f"GitHub update result dispatch failed: {exc}")

        threading.Thread(
            target=worker,
            name="re6-github-update-check",
            daemon=True,
        ).start()

    def _raise_main_window_once_on_startup(self) -> None:
        """Bring the newly created main window forward once, then release it."""
        if self._startup_window_foregrounded or self._closing:
            return
        self._startup_window_foregrounded = True
        try:
            self.root.deiconify()
            self.root.lift()
            self.root.attributes("-topmost", True)
            self.root.focus_force()
        except Exception:
            return

        def release_topmost() -> None:
            if self._closing:
                return
            try:
                self.root.attributes("-topmost", False)
            except Exception:
                pass

        # The temporary topmost flag makes the first visible frame reliable
        # without turning the ARC tool into an always-on-top application.
        self.root.after(600, release_topmost)

    def set_status(self, english: str, chinese: str) -> None:
        self.status_var.set(self.tr(english, chinese))

    @staticmethod
    def _coerce_explorer_navigation_override_state(
        raw_state: Any,
    ) -> dict[str, Any] | None:
        """Validate the exact pre-toggle values used to restore Explorer."""
        if not isinstance(raw_state, dict) or raw_state.get("enabled") is not True:
            return None
        raw_values = raw_state.get("values")
        if not isinstance(raw_values, dict):
            return None

        values: dict[str, dict[str, int | bool]] = {}
        for value_name in EXPLORER_NAVIGATION_REGISTRY_VALUE_NAMES:
            raw_value = raw_values.get(value_name)
            if not isinstance(raw_value, dict):
                return None
            exists = raw_value.get("exists")
            if not isinstance(exists, bool):
                return None
            if not exists:
                values[value_name] = {"exists": False}
                continue
            data = raw_value.get("value")
            if isinstance(data, bool):
                return None
            try:
                numeric_data = int(data)
            except (TypeError, ValueError):
                return None
            if not 0 <= numeric_data <= 0xFFFFFFFF:
                return None
            values[value_name] = {"exists": True, "value": numeric_data}

        return {"enabled": True, "values": values}

    @staticmethod
    def _explorer_navigation_override_is_supported() -> bool:
        return os.name == "nt" and winreg is not None

    def _read_explorer_navigation_registry_values(self) -> dict[str, dict[str, int | bool]]:
        """Read only the two native Explorer settings this tool owns."""
        if not self._explorer_navigation_override_is_supported():
            raise RuntimeError("Windows Explorer navigation settings are available on Windows only.")
        assert winreg is not None
        values: dict[str, dict[str, int | bool]] = {}
        with winreg.OpenKey(
            winreg.HKEY_CURRENT_USER,
            EXPLORER_ADVANCED_REGISTRY_SUBKEY,
            0,
            winreg.KEY_READ,
        ) as key:
            for value_name in EXPLORER_NAVIGATION_REGISTRY_VALUE_NAMES:
                try:
                    value, value_type = winreg.QueryValueEx(key, value_name)
                except FileNotFoundError:
                    values[value_name] = {"exists": False}
                    continue
                if value_type != winreg.REG_DWORD or isinstance(value, bool):
                    raise RuntimeError(
                        f"Unexpected Explorer registry type for {value_name}."
                    )
                values[value_name] = {"exists": True, "value": int(value)}
        return values

    def _write_explorer_navigation_registry_values(
        self,
        raw_values: dict[str, dict[str, int | bool]],
    ) -> None:
        """Apply a validated native Explorer settings snapshot."""
        state = self._coerce_explorer_navigation_override_state(
            {"enabled": True, "values": raw_values}
        )
        if state is None:
            raise RuntimeError("Invalid Explorer navigation settings snapshot.")
        if not self._explorer_navigation_override_is_supported():
            raise RuntimeError("Windows Explorer navigation settings are available on Windows only.")
        assert winreg is not None
        values = state["values"]
        with winreg.CreateKeyEx(
            winreg.HKEY_CURRENT_USER,
            EXPLORER_ADVANCED_REGISTRY_SUBKEY,
            0,
            winreg.KEY_SET_VALUE | winreg.KEY_QUERY_VALUE,
        ) as key:
            for value_name in EXPLORER_NAVIGATION_REGISTRY_VALUE_NAMES:
                value_state = values[value_name]
                if bool(value_state["exists"]):
                    winreg.SetValueEx(
                        key,
                        value_name,
                        0,
                        winreg.REG_DWORD,
                        int(value_state["value"]),
                    )
                    continue
                try:
                    winreg.DeleteValue(key, value_name)
                except FileNotFoundError:
                    pass

    def _notify_explorer_navigation_settings_changed(self) -> None:
        """Ask existing Explorer windows to reread the native navigation settings."""
        if os.name != "nt":
            return
        try:
            result = ctypes.c_size_t()
            ctypes.windll.user32.SendMessageTimeoutW(
                0xFFFF,
                0x001A,
                0,
                EXPLORER_ADVANCED_REGISTRY_SUBKEY,
                0x0002,
                1000,
                ctypes.byref(result),
            )
        except Exception as exc:
            runtime_log(f"Explorer navigation settings notification failed: {exc}")

    def toggle_windows_explorer_navigation_mode(self) -> None:
        """Toggle native Explorer tree/follow settings and restore exact prior values."""
        requested_enabled = bool(self.explorer_navigation_var.get())
        active_state = self._coerce_explorer_navigation_override_state(
            getattr(self, "_explorer_navigation_override_state", None)
        )

        if requested_enabled:
            if active_state is not None:
                self.refresh_toolbar_toggle_labels()
                return
            previous_values: dict[str, dict[str, int | bool]] | None = None
            try:
                previous_values = self._read_explorer_navigation_registry_values()
                new_state = {
                    "enabled": True,
                    "values": previous_values,
                }
                # Persist the restoration point before modifying a user setting.
                self._explorer_navigation_override_state = new_state
                self._save_ui_settings()
                self._write_explorer_navigation_registry_values(
                    {
                        value_name: {"exists": True, "value": 1}
                        for value_name in EXPLORER_NAVIGATION_REGISTRY_VALUE_NAMES
                    }
                )
            except Exception as exc:
                if previous_values is not None:
                    try:
                        self._write_explorer_navigation_registry_values(previous_values)
                    except Exception:
                        pass
                self._explorer_navigation_override_state = None
                self.explorer_navigation_var.set(False)
                self._save_ui_settings()
                runtime_log(f"Explorer navigation enable failed: {exc}")
                self.set_status(
                    "Windows Explorer navigation setting could not be enabled.",
                    "无法启用 Windows 资源管理器导航栏设置。",
                )
                self.refresh_toolbar_toggle_labels()
                return

            self._notify_explorer_navigation_settings_changed()
            self.explorer_navigation_var.set(True)
            self._save_ui_settings()
            self.set_status(
                "Windows Explorer native tree follow is enabled.",
                "已启用 Windows 资源管理器原生左侧树状追随。",
            )
            self.refresh_toolbar_toggle_labels()
            return

        if active_state is None:
            self.explorer_navigation_var.set(False)
            self.refresh_toolbar_toggle_labels()
            return
        try:
            self._write_explorer_navigation_registry_values(active_state["values"])
        except Exception as exc:
            self.explorer_navigation_var.set(True)
            runtime_log(f"Explorer navigation restore failed: {exc}")
            self.set_status(
                "Windows Explorer navigation setting could not be restored.",
                "无法恢复 Windows 资源管理器导航栏原设置。",
            )
            self.refresh_toolbar_toggle_labels()
            return

        self._notify_explorer_navigation_settings_changed()
        self._explorer_navigation_override_state = None
        self.explorer_navigation_var.set(False)
        self._save_ui_settings()
        self.set_status(
            "Windows Explorer navigation settings were restored.",
            "已恢复 Windows 资源管理器导航栏原设置。",
        )
        self.refresh_toolbar_toggle_labels()

    def _poll_foreground_explorer_window(self) -> None:
        """Retired with the custom Explorer mirror; retained as a harmless shim."""
        return
        if self._closing:
            return
        if os.name == "nt":
            try:
                import win32gui

                hwnd = int(win32gui.GetForegroundWindow() or 0)
                class_name = str(win32gui.GetClassName(hwnd) or "") if hwnd else ""
                if class_name in {"CabinetWClass", "ExploreWClass"}:
                    changed = hwnd != int(self._last_foreground_explorer_hwnd or 0)
                    self._last_foreground_explorer_hwnd = hwnd
                    if changed and callable(self._directory_jump_assistant_refresh):
                        self.root.after_idle(self._directory_jump_assistant_refresh)
            except Exception:
                pass
        try:
            self.root.after(250, self._poll_foreground_explorer_window)
        except Exception:
            pass

    def _windows_explorer_records(self) -> list[dict[str, Any]]:
        """Return filesystem-backed Windows Explorer tabs/windows via Shell COM."""
        if os.name != "nt":
            return []
        initialized = False
        try:
            import pythoncom
            import win32com.client
            import win32gui

            pythoncom.CoInitialize()
            initialized = True
            foreground_hwnd = int(win32gui.GetForegroundWindow() or 0)
            explorer_z_order: dict[int, int] = {}

            def collect_explorer_z_order(hwnd: int, _extra: Any) -> bool:
                try:
                    class_name = str(win32gui.GetClassName(hwnd) or "")
                    if class_name in {"CabinetWClass", "ExploreWClass"}:
                        explorer_z_order.setdefault(int(hwnd), len(explorer_z_order))
                except Exception:
                    pass
                return True

            win32gui.EnumWindows(collect_explorer_z_order, None)
            shell = win32com.client.Dispatch("Shell.Application")
            records: list[dict[str, Any]] = []
            seen: set[tuple[int, str]] = set()
            for shell_window in shell.Windows():
                try:
                    hwnd = int(shell_window.HWND)
                    path_text = str(shell_window.Document.Folder.Self.Path or "").strip()
                    if not path_text or path_text.startswith("::"):
                        continue
                    path = Path(path_text)
                    if not path.is_dir():
                        continue
                    normalized_path = os.path.normcase(os.path.normpath(str(path)))
                    identity = (hwnd, normalized_path)
                    if identity in seen:
                        continue
                    seen.add(identity)
                    try:
                        title = str(shell_window.LocationName or "").strip()
                    except Exception:
                        title = ""
                    records.append(
                        {
                            "hwnd": hwnd,
                            "path": str(path),
                            "normalized_path": normalized_path,
                            "title": title or path.name or str(path),
                        }
                    )
                except Exception:
                    continue
            last_hwnd = int(self._last_foreground_explorer_hwnd or 0)
            records.sort(
                key=lambda item: (
                    0 if int(item["hwnd"]) == foreground_hwnd else 1,
                    explorer_z_order.get(
                        int(item["hwnd"]),
                        500000 if int(item["hwnd"]) == last_hwnd else 999999,
                    ),
                    str(item["title"]).casefold(),
                    str(item["path"]).casefold(),
                )
            )
            return records
        except Exception as exc:
            runtime_log(f"Windows Explorer discovery failed: {exc}")
            return []
        finally:
            if initialized:
                try:
                    pythoncom.CoUninitialize()
                except Exception:
                    pass

    def _preferred_foreground_explorer_record(
        self,
        records: list[dict[str, Any]],
    ) -> dict[str, Any] | None:
        """Return the Explorer that the foreground watcher last observed."""
        last_hwnd = int(self._last_foreground_explorer_hwnd or 0)
        if last_hwnd:
            for record in records:
                if int(record.get("hwnd") or 0) == last_hwnd:
                    return record
        return records[0] if records else None

    def _active_windows_explorer_path_from_uia(self, hwnd: int) -> Path | None:
        """Read the active Explorer tab's filesystem path from its breadcrumbs."""
        if os.name != "nt" or not hwnd:
            return None
        initialized = False
        try:
            import comtypes
            import comtypes.client
            from comtypes import CLSCTX_INPROC_SERVER

            comtypes.CoInitialize()
            initialized = True
            comtypes.client.GetModule("UIAutomationCore.dll")
            from comtypes.gen import UIAutomationClient as uia

            automation = comtypes.CoCreateInstance(
                uia.CUIAutomation._reg_clsid_,
                interface=uia.IUIAutomation,
                clsctx=CLSCTX_INPROC_SERVER,
            )
            root = automation.ElementFromHandle(int(hwnd))
            elements = root.FindAll(
                uia.TreeScope_Subtree,
                automation.CreateTrueCondition(),
            )
            breadcrumb_parts: list[str] = []
            for index in range(int(elements.Length)):
                element = elements.GetElement(index)
                class_name = str(element.CurrentClassName or "")
                if "BreadcrumbBarItemControl" not in class_name:
                    continue
                name = str(element.CurrentName or "").strip()
                if name:
                    breadcrumb_parts.append(name)

            for index, part in enumerate(breadcrumb_parts):
                drive_match = re.search(r"([A-Za-z]:)", part)
                if drive_match is None:
                    continue
                candidate = Path(f"{drive_match.group(1)}\\")
                for child_part in breadcrumb_parts[index + 1 :]:
                    candidate /= child_part
                if candidate.is_dir():
                    return candidate
        except Exception as exc:
            runtime_log(f"Windows Explorer UI Automation path probe failed: {exc}")
        finally:
            if initialized:
                try:
                    comtypes.CoUninitialize()
                except Exception:
                    pass
        return None

    def _live_foreground_explorer_record(self) -> dict[str, Any] | None:
        """Resolve the live filesystem path for the active Explorer tab."""
        records = self._windows_explorer_records()
        record = self._preferred_foreground_explorer_record(records)
        if record is None:
            return None
        active_path = self._active_windows_explorer_path_from_uia(
            int(record.get("hwnd") or 0)
        )
        if active_path is None:
            return record
        normalized_path = os.path.normcase(os.path.normpath(str(active_path)))
        for candidate in records:
            if (
                int(candidate.get("hwnd") or 0) == int(record.get("hwnd") or 0)
                and str(candidate.get("normalized_path") or "") == normalized_path
            ):
                return candidate
        live_record = dict(record)
        live_record["path"] = str(active_path)
        live_record["normalized_path"] = normalized_path
        live_record["title"] = active_path.name or str(active_path)
        return live_record

    def _invoke_windows_explorer(
        self,
        record: dict[str, Any],
        action: str,
        target_path: Path | None = None,
    ) -> tuple[bool, str]:
        """Run one navigation action on the selected Explorer tab/window."""
        if os.name != "nt":
            return False, self.tr(
                "Windows Explorer control is available on Windows only.",
                "Windows 资源管理器控制仅在 Windows 可用。",
            )
        initialized = False
        try:
            import pythoncom
            import win32com.client
            import win32gui

            pythoncom.CoInitialize()
            initialized = True
            target_hwnd = int(record.get("hwnd") or 0)
            recorded_path = os.path.normcase(
                os.path.normpath(str(record.get("path") or ""))
            )
            shell = win32com.client.Dispatch("Shell.Application")
            selected_window: Any = None
            hwnd_fallback: Any = None
            for shell_window in shell.Windows():
                try:
                    if int(shell_window.HWND) != target_hwnd:
                        continue
                    hwnd_fallback = shell_window
                    current_path = os.path.normcase(
                        os.path.normpath(
                            str(shell_window.Document.Folder.Self.Path or "")
                        )
                    )
                    if current_path == recorded_path:
                        selected_window = shell_window
                        break
                except Exception:
                    continue
            selected_window = selected_window or hwnd_fallback
            if selected_window is None:
                return False, self.tr(
                    "The selected Windows Explorer window is no longer available.",
                    "选中的 Windows 资源管理器窗口已不可用。",
                )
            if action == "navigate":
                if target_path is None or not target_path.is_dir():
                    return False, self.tr(
                        "The target folder is unavailable.",
                        "目标文件夹不可用。",
                    )
                selected_window.Navigate2(str(target_path))
            elif action == "back":
                selected_window.GoBack()
            elif action == "forward":
                selected_window.GoForward()
            else:
                return False, self.tr(
                    "Unknown Explorer navigation action.",
                    "未知的资源管理器导航操作。",
                )
            try:
                win32gui.ShowWindow(target_hwnd, 9)
                win32gui.BringWindowToTop(target_hwnd)
                win32gui.SetForegroundWindow(target_hwnd)
            except Exception:
                pass
            return True, ""
        except Exception as exc:
            runtime_log(f"Windows Explorer navigation failed: action={action}; {exc}")
            return False, str(exc)
        finally:
            if initialized:
                try:
                    pythoncom.CoUninitialize()
                except Exception:
                    pass

    def open_windows_directory_jump_assistant(self) -> None:
        """Compatibility entry point for callers from older saved UI bindings."""
        self.explorer_navigation_var.set(
            not bool(self.explorer_navigation_var.get())
        )
        self.toggle_windows_explorer_navigation_mode()
        return
        existing = self._directory_jump_assistant_window
        if self._window_is_alive(existing):
            try:
                existing.deiconify()
                existing.attributes("-topmost", True)
                existing.lift()
                existing.focus_force()
            except Exception:
                pass
            if callable(self._directory_jump_assistant_refresh):
                self._directory_jump_assistant_refresh()
            return

        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("Windows Folder Jump Assistant", "Windows 目录跳转助手"))
        dialog.transient(self.root)
        dialog.resizable(True, True)
        dialog.minsize(760, 420)
        dialog.geometry("940x560")
        self._directory_jump_assistant_window = dialog
        try:
            dialog.attributes("-topmost", True)
        except Exception:
            pass

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill="both", expand=True)
        body.columnconfigure(0, weight=1)
        body.rowconfigure(2, weight=1)

        assistant_path_var = tk.StringVar()
        helper_status_var = tk.StringVar()
        folder_count_var = tk.StringVar()
        state: dict[str, Any] = {
            "record": None,
            "root_path": None,
            "root_item": "",
            "tree_nodes": {},
            "tree_revision": 0,
            "observed_explorer_identity": "",
            "probe_active": False,
            "probe_pending": False,
            "probe_serial": 0,
        }
        explorer_probe_queue: queue.Queue[tuple[int, dict[str, Any] | None, str]] = (
            queue.Queue()
        )

        ttk.Label(
            body,
            text=self.tr("Windows Explorer Directory Tree", "Windows 资源管理器目录树"),
            font=(UI_FONT_FAMILY, 11, "bold"),
        ).grid(row=0, column=0, sticky="w")

        path_row = ttk.Frame(body)
        path_row.grid(row=1, column=0, sticky="ew", pady=(8, 0))
        path_row.columnconfigure(0, weight=1)
        ttk.Label(
            path_row,
            textvariable=assistant_path_var,
            style="ExplorerJumpPath.TLabel",
            anchor="w",
        ).grid(row=0, column=0, sticky="ew")

        tree_wrap = ttk.Frame(body)
        tree_wrap.grid(row=2, column=0, sticky="nsew", pady=(12, 0))
        tree_wrap.columnconfigure(0, weight=1)
        tree_wrap.rowconfigure(0, weight=1)
        folder_tree = ttk.Treeview(
            tree_wrap,
            columns=("go",),
            show="tree headings",
            selectmode="browse",
        )
        folder_tree.heading("#0", text=self.tr("Windows Directory Hierarchy", "Windows 文件层级"))
        folder_tree.heading("go", text=self.tr("Go", "转到"))
        folder_tree.column("#0", width=720, minwidth=300, stretch=True, anchor="w")
        folder_tree.column("go", width=80, minwidth=70, stretch=False, anchor="center")
        scrollbar = self._create_themed_scrollbar(
            tree_wrap,
            orient="vertical",
            command=folder_tree.yview,
        )
        folder_tree.configure(yscrollcommand=scrollbar.set)
        folder_tree.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")

        status_row = ttk.Frame(body)
        status_row.grid(row=3, column=0, sticky="ew", pady=(12, 0))
        ttk.Label(
            status_row,
            textvariable=folder_count_var,
            style="ExplorerJumpStatus.TLabel",
        ).pack(side="left")
        ttk.Label(
            status_row,
            textvariable=helper_status_var,
            style="ExplorerJumpStatus.TLabel",
        ).pack(side="left", padx=(14, 0))

        def path_key(path: Path) -> str:
            return os.path.normcase(os.path.normpath(str(path)))

        def clear_tree() -> None:
            for item_id in folder_tree.get_children(""):
                folder_tree.delete(item_id)
            state["tree_nodes"] = {}
            state["root_item"] = ""

        def discard_tree_node(item_id: str) -> None:
            for child_id in folder_tree.get_children(item_id):
                discard_tree_node(child_id)
            tree_nodes = state["tree_nodes"]
            if isinstance(tree_nodes, dict):
                tree_nodes.pop(item_id, None)

        def insert_tree_node(parent_id: str, path: Path, is_directory: bool) -> str:
            label = path.name or str(path)
            item_id = folder_tree.insert(
                parent_id,
                "end",
                text=label,
                values=(self.tr("Go", "转到"),) if is_directory else ("",),
            )
            tree_nodes = state["tree_nodes"]
            assert isinstance(tree_nodes, dict)
            tree_nodes[item_id] = {
                "path": path,
                "is_directory": is_directory,
                "loaded": not is_directory,
            }
            if is_directory:
                # A placeholder provides the expand arrow before the directory
                # has been read, so opening a large Explorer path stays cheap.
                folder_tree.insert(item_id, "end", text="")
            return item_id

        def populate_directory_node(item_id: str) -> tuple[int, int]:
            tree_nodes = state["tree_nodes"]
            if not isinstance(tree_nodes, dict):
                return 0, 0
            node = tree_nodes.get(item_id)
            if not isinstance(node, dict) or not node.get("is_directory"):
                return 0, 0
            if node.get("loaded"):
                return 0, 0
            for child_id in folder_tree.get_children(item_id):
                discard_tree_node(child_id)
                folder_tree.delete(child_id)
            node["loaded"] = True
            path = Path(node["path"])
            try:
                entries = list(path.iterdir())
            except OSError as exc:
                helper_status_var.set(
                    self.tr(
                        f"Cannot read {path}: {exc}",
                        f"无法读取 {path}: {exc}",
                    )
                )
                return 0, 0
            directories: list[Path] = []
            files: list[Path] = []
            for entry in entries:
                try:
                    if entry.is_dir():
                        directories.append(entry)
                    else:
                        files.append(entry)
                except OSError:
                    continue
            directories.sort(key=lambda item: item.name.casefold())
            files.sort(key=lambda item: item.name.casefold())
            for directory in directories:
                insert_tree_node(item_id, directory, True)
            for file_path in files:
                insert_tree_node(item_id, file_path, False)
            return len(directories), len(files)

        def schedule_default_expansion(root_item: str) -> None:
            """Expand each level in small UI batches after an Explorer switch."""
            pending: list[str] = [root_item]
            revision = int(state.get("tree_revision") or 0)

            def expand_batch() -> None:
                if (
                    not self._window_is_alive(dialog)
                    or not pending
                    or revision != int(state.get("tree_revision") or 0)
                ):
                    return
                for _index in range(18):
                    if not pending:
                        break
                    item_id = pending.pop(0)
                    tree_nodes = state.get("tree_nodes")
                    node = tree_nodes.get(item_id) if isinstance(tree_nodes, dict) else None
                    if not isinstance(node, dict) or not node.get("is_directory"):
                        continue
                    populate_directory_node(item_id)
                    folder_tree.item(item_id, open=True)
                    for child_id in folder_tree.get_children(item_id):
                        child_node = tree_nodes.get(child_id) if isinstance(tree_nodes, dict) else None
                        if isinstance(child_node, dict) and child_node.get("is_directory"):
                            pending.append(child_id)
                if pending:
                    dialog.after(1, expand_batch)

            dialog.after(1, expand_batch)

        def rebuild_tree(root_path: Path) -> None:
            state["tree_revision"] = int(state.get("tree_revision") or 0) + 1
            clear_tree()
            state["root_path"] = root_path
            assistant_path_var.set(str(root_path))
            root_item = insert_tree_node("", root_path, True)
            state["root_item"] = root_item
            folder_tree.item(root_item, open=True)
            directory_count, file_count = populate_directory_node(root_item)
            schedule_default_expansion(root_item)
            folder_count_var.set(
                self.tr(
                    f"Root: {directory_count} folders, {file_count} files",
                    f"根目录：{directory_count} 个文件夹，{file_count} 个文件",
                )
            )

        def apply_explorer_record(record: dict[str, Any] | None) -> None:
            if record is None:
                if state.get("record") is not None:
                    clear_tree()
                state["record"] = None
                state["observed_explorer_identity"] = ""
                folder_count_var.set("")
                assistant_path_var.set(
                    self.tr(
                        "Waiting for a foreground Windows Explorer window...",
                        "等待前置的 Windows 资源管理器窗口...",
                    )
                )
                helper_status_var.set(
                    self.tr(
                        "No Windows Explorer window is available.",
                        "没有可用的 Windows 资源管理器窗口。",
                    )
                )
                return

            current_path = Path(str(record.get("path") or ""))
            if not current_path.is_dir():
                helper_status_var.set(
                    self.tr(
                        "The foreground Explorer folder is unavailable.",
                        "前置资源管理器目录不可用。",
                    )
                )
                return
            explorer_identity = f"{int(record.get('hwnd') or 0)}:{path_key(current_path)}"
            assistant_path_var.set(str(current_path))
            if explorer_identity == str(state.get("observed_explorer_identity") or ""):
                return

            state["record"] = record
            state["observed_explorer_identity"] = explorer_identity
            rebuild_tree(current_path)
            helper_status_var.set(
                self.tr(
                    f"Live sync: {current_path}",
                    f"实时同步：{current_path}",
                )
            )

        def refresh_explorer_windows() -> None:
            if bool(state.get("probe_active")):
                state["probe_pending"] = True
                return
            state["probe_active"] = True
            state["probe_serial"] = int(state.get("probe_serial") or 0) + 1
            serial = int(state["probe_serial"])

            def probe_worker() -> None:
                try:
                    record = self._live_foreground_explorer_record()
                    explorer_probe_queue.put((serial, record, ""))
                except Exception as exc:
                    explorer_probe_queue.put((serial, None, str(exc)))

            threading.Thread(
                target=probe_worker,
                name="re6-live-explorer-probe",
                daemon=True,
            ).start()

            def consume_probe_result() -> None:
                if not self._window_is_alive(dialog):
                    return
                result: tuple[int, dict[str, Any] | None, str] | None = None
                while True:
                    try:
                        candidate = explorer_probe_queue.get_nowait()
                    except queue.Empty:
                        break
                    if candidate[0] == serial:
                        result = candidate
                        break
                if result is None:
                    dialog.after(50, consume_probe_result)
                    return

                state["probe_active"] = False
                _result_serial, record, error_text = result
                if error_text:
                    helper_status_var.set(error_text)
                else:
                    apply_explorer_record(record)
                if bool(state.get("probe_pending")):
                    state["probe_pending"] = False
                    dialog.after(0, refresh_explorer_windows)

            dialog.after(50, consume_probe_result)

        def navigate_windows_explorer(target_path: Path) -> None:
            record = state.get("record")
            if not isinstance(record, dict):
                helper_status_var.set(
                    self.tr(
                        "No Windows Explorer window is available.",
                        "没有可用的 Windows 资源管理器窗口。",
                    )
                )
                return
            succeeded, message = self._invoke_windows_explorer(
                record,
                "navigate",
                target_path,
            )
            if not succeeded:
                helper_status_var.set(
                    message
                    or self.tr(
                        "Windows Explorer navigation failed.",
                        "Windows 资源管理器导航失败。",
                    )
                )
                return
            state["observed_explorer_identity"] = ""
            helper_status_var.set(self.tr("Explorer updated.", "资源管理器已跳转。"))
            dialog.after(120, refresh_explorer_windows)

        def on_tree_open(_event: tk.Event) -> None:
            item_id = folder_tree.focus()
            directory_count, file_count = populate_directory_node(item_id)
            if directory_count or file_count:
                folder_count_var.set(
                    self.tr(
                        f"Loaded: {directory_count} folders, {file_count} files",
                        f"已加载：{directory_count} 个文件夹，{file_count} 个文件",
                    )
                )

        def on_tree_click(event: tk.Event) -> str | None:
            if folder_tree.identify_column(event.x) != "#1":
                return None
            item_id = folder_tree.identify_row(event.y)
            tree_nodes = state.get("tree_nodes")
            node = tree_nodes.get(item_id) if isinstance(tree_nodes, dict) else None
            if isinstance(node, dict) and node.get("is_directory"):
                folder_tree.focus(item_id)
                folder_tree.selection_set(item_id)
                navigate_windows_explorer(Path(node["path"]))
                return "break"
            return None

        def on_tree_double_click(event: tk.Event) -> str | None:
            item_id = folder_tree.identify_row(event.y)
            tree_nodes = state.get("tree_nodes")
            node = tree_nodes.get(item_id) if isinstance(tree_nodes, dict) else None
            if not isinstance(node, dict) or not node.get("is_directory"):
                return None
            is_open = bool(folder_tree.item(item_id, "open"))
            if not is_open:
                populate_directory_node(item_id)
            folder_tree.item(item_id, open=not is_open)
            return "break"

        def toggle_selected_folder() -> None:
            item_id = folder_tree.focus()
            tree_nodes = state.get("tree_nodes")
            node = tree_nodes.get(item_id) if isinstance(tree_nodes, dict) else None
            if not isinstance(node, dict) or not node.get("is_directory"):
                return
            is_open = bool(folder_tree.item(item_id, "open"))
            if not is_open:
                populate_directory_node(item_id)
            folder_tree.item(item_id, open=not is_open)

        folder_tree.bind("<<TreeviewOpen>>", on_tree_open)
        folder_tree.bind("<ButtonRelease-1>", on_tree_click)
        folder_tree.bind("<Double-1>", on_tree_double_click)
        folder_tree.bind("<Return>", lambda _event: toggle_selected_folder())

        def close_dialog() -> None:
            if self._directory_jump_assistant_window is dialog:
                self._directory_jump_assistant_window = None
                self._directory_jump_assistant_refresh = None
            try:
                dialog.attributes("-topmost", False)
            except Exception:
                pass
            dialog.destroy()

        def poll_explorer() -> None:
            if not self._window_is_alive(dialog):
                return
            refresh_explorer_windows()
            dialog.after(250, poll_explorer)

        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        self._apply_toplevel_theme(dialog)
        self._center_dialog(dialog)
        self._directory_jump_assistant_refresh = refresh_explorer_windows
        refresh_explorer_windows()
        dialog.after(250, poll_explorer)

    def _start_audio_dependency_bootstrap(self) -> None:
        if self._closing or (
            self._audio_dependency_worker is not None
            and self._audio_dependency_worker.is_alive()
        ):
            return
        helper_path = find_known_format_helper(self.script_dir)
        if helper_path is None:
            runtime_log("audio dependency bootstrap skipped: known-format helper missing")
            return
        try:
            helper = load_helper_module(helper_path, "re6_audio_dependencies")
        except Exception as exc:
            runtime_log(f"audio dependency helper load failed: {exc}")
            return
        ensure_dependencies = getattr(helper, "ensure_audio_dependencies", None)
        if not callable(ensure_dependencies):
            runtime_log("audio dependency bootstrap skipped: installer API missing")
            return

        def progress(message: str) -> None:
            self._audio_dependency_queue.put(("progress", str(message)))

        def runner() -> None:
            try:
                result = dict(
                    ensure_dependencies(
                        self.script_dir,
                        install_mtf_sound_tool=True,
                        install_ffmpeg=True,
                        progress=progress,
                    )
                )
                self._audio_dependency_queue.put(("done", result))
            except Exception:
                self._audio_dependency_queue.put(("error", traceback.format_exc()))

        self._audio_dependency_worker = threading.Thread(
            target=runner,
            name="re6-audio-dependency-bootstrap",
            daemon=True,
        )
        self._audio_dependency_worker.start()
        self.root.after(120, self._poll_audio_dependency_bootstrap)

    def _poll_audio_dependency_bootstrap(self) -> None:
        completed = False
        while True:
            try:
                kind, payload = self._audio_dependency_queue.get_nowait()
            except queue.Empty:
                break
            if kind == "progress":
                runtime_log(f"audio dependency: {payload}")
                self.set_status(
                    f"Audio dependency: {payload}",
                    f"音频依赖安装：{payload}",
                )
            elif kind == "done":
                completed = True
                result = dict(payload or {})
                installed_count = int(result.get("installed_count", 0) or 0)
                failure_count = int(result.get("failure_count", 0) or 0)
                failures = list(result.get("failures") or [])
                if failure_count:
                    runtime_log(
                        "audio dependency bootstrap failures: "
                        + json.dumps(failures, ensure_ascii=False)
                    )
                    self.set_status(
                        f"Audio dependencies: installed={installed_count}, failed={failure_count}. See log; a proxy may be required.",
                        f"音频依赖：已安装={installed_count}，失败={failure_count}。请查看日志；中国大陆网络可能需要代理。",
                    )
                    failure_details = "\n".join(
                        f"- {str(item.get('name') or 'Unknown')}: {str(item.get('error') or 'Unknown error')}"
                        for item in failures
                        if isinstance(item, dict)
                    )
                    retry = False
                    if messagebox is not None:
                        retry = bool(
                            self._run_native_messagebox(messagebox.askretrycancel,
                                self.tr(
                                    "Audio Dependency Download Failed",
                                    "音频依赖下载失败",
                                ),
                                self.tr(
                                    "One or more required audio executables are still missing. Related functions will continue to report an error until installation succeeds.\n\n"
                                    f"{failure_details}\n\n"
                                    "Check the network connection and retry. GitHub access may require a proxy or VPN in mainland China. All partial downloads have already been removed.",
                                    "一个或多个必需的音频 EXE 仍然缺失。安装成功之前，相关功能会持续报错。\n\n"
                                    f"{failure_details}\n\n"
                                    "请检查网络后重试。中国大陆访问 GitHub 时可能需要代理或 VPN。所有不完整下载已经删除。",
                                ),
                                parent=self.root,
                            )
                        )
                    if retry:
                        self.root.after(400, self._start_audio_dependency_bootstrap)
                elif installed_count:
                    self.set_status(
                        f"Audio dependencies installed: {installed_count}. Temporary downloads removed.",
                        f"音频依赖安装完成：{installed_count} 个，临时下载已删除。",
                    )
                runtime_log(
                    f"audio dependency bootstrap complete installed={installed_count} failed={failure_count}"
                )
            elif kind == "error":
                completed = True
                runtime_log(f"audio dependency bootstrap error: {payload}")
                self.set_status(
                    "Audio dependency installation failed. See runtime log.",
                    "音频依赖自动安装失败，请查看运行日志。",
                )
                retry = False
                if messagebox is not None:
                    retry = bool(
                        self._run_native_messagebox(messagebox.askretrycancel,
                            self.tr(
                                "Audio Dependency Download Failed",
                                "音频依赖下载失败",
                            ),
                            self.tr(
                                "The audio dependency installer failed unexpectedly. Required files remain missing and related functions will keep reporting an error.\n\nRetry now?",
                                "音频依赖安装器发生异常。必需文件仍然缺失，相关功能会持续报错。\n\n是否立即重试？",
                            ),
                            parent=self.root,
                        )
                    )
                if retry:
                    self.root.after(400, self._start_audio_dependency_bootstrap)
        worker_alive = bool(
            self._audio_dependency_worker is not None
            and self._audio_dependency_worker.is_alive()
        )
        if worker_alive or not completed:
            if not self._closing:
                self.root.after(120, self._poll_audio_dependency_bootstrap)
            return
        self._audio_dependency_worker = None

    def _center_dialog(self, dialog: tk.Misc) -> None:
        dialog.update_idletasks()
        width = max(1, int(dialog.winfo_width()))
        height = max(1, int(dialog.winfo_height()))
        root_x = int(self.root.winfo_rootx())
        root_y = int(self.root.winfo_rooty())
        root_width = max(1, int(self.root.winfo_width()))
        root_height = max(1, int(self.root.winfo_height()))
        x = root_x + max(0, (root_width - width) // 2)
        y = root_y + max(0, (root_height - height) // 2)
        dialog.geometry(f"+{x}+{y}")

    def _workspace_reveal_state(self, dialog: tk.Misc | None) -> dict[str, Any] | None:
        if dialog is None:
            return None
        states = getattr(self, "_workspace_reveal_dialogs", {})
        return states.get(self._drop_window_key(dialog))

    def _set_workspace_dialog_alpha(
        self,
        dialog: tk.Misc,
        hwnd: int | None,
        alpha: float,
        state: dict[str, Any],
    ) -> None:
        if os.name != "nt" or hwnd is None:
            try:
                dialog.attributes("-alpha", max(0.2, min(1.0, float(alpha))))
            except Exception:
                pass
            return
        try:
            user32 = ctypes.windll.user32
            user32.GetWindowLongW.argtypes = [wintypes.HWND, ctypes.c_int]
            user32.GetWindowLongW.restype = ctypes.c_long
            user32.SetWindowLongW.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_long]
            user32.SetWindowLongW.restype = ctypes.c_long
            user32.SetLayeredWindowAttributes.argtypes = [
                wintypes.HWND,
                wintypes.COLORREF,
                wintypes.BYTE,
                wintypes.DWORD,
            ]
            user32.SetLayeredWindowAttributes.restype = wintypes.BOOL
            if "original_ex_style" not in state:
                state["original_ex_style"] = int(user32.GetWindowLongW(hwnd, GWL_EXSTYLE))
            original_style = int(state.get("original_ex_style", 0))
            user32.SetWindowLongW(hwnd, GWL_EXSTYLE, original_style | WS_EX_LAYERED)
            user32.SetLayeredWindowAttributes(
                hwnd,
                0,
                max(1, min(255, int(round(float(alpha) * 255.0)))),
                LWA_ALPHA,
            )
            if float(alpha) >= 1.0 and not (original_style & WS_EX_LAYERED):
                user32.SetWindowLongW(hwnd, GWL_EXSTYLE, original_style)
                state.pop("original_ex_style", None)
        except Exception:
            return

    def _enable_dialog_workspace_reveal(
        self,
        dialog: tk.Toplevel,
        *,
        show_drop_hint: bool = False,
    ) -> None:
        key = self._drop_window_key(dialog)
        state: dict[str, Any] = {
            "active": False,
            "moving": False,
            "configure_armed": False,
            "last_geometry": None,
            "move_end_after_id": None,
            "original_geometry": None,
            "original_minsize": None,
            "original_transient": "",
            "root_state": "normal",
        }
        self._workspace_reveal_dialogs[key] = state
        self._register_drop_window(dialog)

        if show_drop_hint:
            hint = ttk.Label(
                dialog,
                text=self.tr(
                    "You can drag files into this window",
                    "您可拖拽文件进入本窗口",
                ),
                style="WorkspaceDropHint.TLabel",
                anchor="center",
                justify="center",
                padding=(10, 7),
            )
            hint.pack(fill="x", padx=14, pady=(10, 0))
            state["drop_hint"] = hint

        def on_destroy(event: Any, target: tk.Toplevel = dialog) -> None:
            if getattr(event, "widget", None) is not target:
                return
            self._restore_dialog_workspace_reveal(target, destroyed=True)

        def arm_configure_tracking(target: tk.Toplevel = dialog) -> None:
            reveal_state = self._workspace_reveal_state(target)
            if reveal_state is None or not self._window_is_alive(target):
                return
            try:
                target.update_idletasks()
                reveal_state["last_geometry"] = (
                    int(target.winfo_width()),
                    int(target.winfo_height()),
                    int(target.winfo_x()),
                    int(target.winfo_y()),
                )
                reveal_state["configure_armed"] = True
            except Exception:
                pass

        def finish_move(target: tk.Toplevel = dialog) -> None:
            reveal_state = self._workspace_reveal_state(target)
            if reveal_state is None:
                return
            reveal_state["move_end_after_id"] = None
            self._workspace_dialog_native_move_end(
                target,
                self._native_window_handle_for(target),
            )

        def schedule_move_end(target: tk.Toplevel = dialog) -> None:
            reveal_state = self._workspace_reveal_state(target)
            if reveal_state is None or not self._window_is_alive(target):
                return
            previous_after_id = reveal_state.get("move_end_after_id")
            if previous_after_id:
                try:
                    target.after_cancel(previous_after_id)
                except Exception:
                    pass
            try:
                reveal_state["move_end_after_id"] = target.after(180, finish_move)
            except Exception:
                reveal_state["move_end_after_id"] = None

        def on_configure(event: Any, target: tk.Toplevel = dialog) -> None:
            if getattr(event, "widget", None) is not target:
                return
            reveal_state = self._workspace_reveal_state(target)
            if reveal_state is None:
                return
            current_geometry = (
                int(getattr(event, "width", target.winfo_width())),
                int(getattr(event, "height", target.winfo_height())),
                int(getattr(event, "x", target.winfo_x())),
                int(getattr(event, "y", target.winfo_y())),
            )
            previous_geometry = reveal_state.get("last_geometry")
            reveal_state["last_geometry"] = current_geometry
            if not bool(reveal_state.get("configure_armed")) or previous_geometry is None:
                return
            # Window dragging must never resize or fade the dialog.  The old
            # workspace-reveal path scaled the popup after a title-bar move,
            # which made its controls disappear.  Keep geometry tracking only.
            del previous_geometry

        dialog.bind("<Destroy>", on_destroy, add="+")
        dialog.bind("<Configure>", on_configure, add="+")
        try:
            dialog.after(180, arm_configure_tracking)
        except Exception:
            pass

    def _workspace_dialog_native_move_begin(self, dialog: tk.Misc, hwnd: int | None) -> None:
        state = self._workspace_reveal_state(dialog)
        if state is None or bool(state.get("moving")):
            return
        state["moving"] = True
        self._set_workspace_dialog_alpha(
            dialog,
            hwnd,
            DIALOG_WORKSPACE_REVEAL_ALPHA,
            state,
        )

    def _workspace_dialog_native_move_end(self, dialog: tk.Misc, hwnd: int | None) -> None:
        state = self._workspace_reveal_state(dialog)
        if state is None:
            return
        if not bool(state.get("moving")):
            return
        # Keep the compact workspace-reveal size after the drag. Only opacity
        # returns to normal; the safe content-size floor is enforced when the
        # compact geometry is calculated in _activate_dialog_workspace_reveal.
        state["moving"] = False
        self._set_workspace_dialog_alpha(dialog, hwnd, 1.0, state)
        runtime_log(f"workspace reveal move ended window={self._drop_window_key(dialog)}")

    @staticmethod
    def _workspace_reveal_content_floor(
        requested_width: int,
        requested_height: int,
        configured_minsize: tuple[int, int],
    ) -> tuple[int, int]:
        """Return the smallest popup size that can still display its content."""
        configured_width, configured_height = configured_minsize
        return (
            max(1, int(requested_width), int(configured_width)),
            max(1, int(requested_height), int(configured_height)),
        )

    def _activate_dialog_workspace_reveal(self, dialog: tk.Misc) -> None:
        state = self._workspace_reveal_state(dialog)
        if state is None or bool(state.get("active")) or not self._window_is_alive(dialog):
            return
        try:
            dialog.update_idletasks()
            width = max(1, int(dialog.winfo_width()))
            height = max(1, int(dialog.winfo_height()))
            state["original_geometry"] = (width, height)
            state["original_minsize"] = tuple(int(value) for value in dialog.minsize())
            state["original_transient"] = str(dialog.transient() or "")
            if getattr(self, "_workspace_reveal_root_state", None) is None:
                self._workspace_reveal_root_state = str(self.root.state())
            state["root_state"] = str(self._workspace_reveal_root_state or "normal")
            state["active"] = True

            dialog.tk.call("wm", "transient", dialog._w, "")
            # Keep the user-selected popup size.  This legacy entry point is
            # retained for compatibility, but it must never resize a dialog.
            self._minimize_root_for_dialog(dialog)
            dialog.deiconify()
            dialog.lift()
            dialog.focus_force()
            runtime_log(
                f"workspace reveal active window={self._drop_window_key(dialog)} "
                f"size={width}x{height}"
            )
        except Exception:
            runtime_log("workspace reveal activation failed")
            runtime_log(traceback.format_exc().rstrip())
            self._restore_dialog_workspace_reveal(dialog)

    def _restore_dialog_workspace_reveal(
        self,
        dialog: tk.Misc,
        *,
        destroyed: bool = False,
    ) -> None:
        key = self._drop_window_key(dialog)
        states = getattr(self, "_workspace_reveal_dialogs", {})
        state = states.get(key)
        if state is None:
            return
        was_active = bool(state.get("active"))
        state["active"] = False
        state["moving"] = False
        move_end_after_id = state.get("move_end_after_id")
        state["move_end_after_id"] = None
        if move_end_after_id and not destroyed and self._window_is_alive(dialog):
            try:
                dialog.after_cancel(move_end_after_id)
            except Exception:
                pass

        if not destroyed and self._window_is_alive(dialog):
            try:
                # Restore the detached popup while it is still independent;
                # reattaching it before deiconifying can leave Tk withdrawn.
                dialog.deiconify()
                hwnd = self._native_window_handle_for(dialog)
                self._set_workspace_dialog_alpha(dialog, hwnd, 1.0, state)
                original_minsize = state.get("original_minsize")
                if original_minsize is not None:
                    dialog.minsize(int(original_minsize[0]), int(original_minsize[1]))
                original_geometry = state.get("original_geometry")
                if original_geometry is not None:
                    width, height = (int(original_geometry[0]), int(original_geometry[1]))
                    dialog.geometry(f"{width}x{height}+{int(dialog.winfo_x())}+{int(dialog.winfo_y())}")
            except Exception:
                pass

        if destroyed:
            states.pop(key, None)
        other_active = any(bool(item.get("active")) for item in states.values())

        if was_active and not other_active and not bool(getattr(self, "_closing", False)):
            try:
                original_root_state = str(
                    self._workspace_reveal_root_state or state.get("root_state") or "normal"
                )
                if original_root_state not in {"iconic", "withdrawn"} and str(self.root.state()) in {
                    "iconic",
                    "withdrawn",
                }:
                    self.root.deiconify()
                if original_root_state == "zoomed":
                    self.root.state("zoomed")
                if not destroyed and self._window_is_alive(dialog):
                    original_transient = str(state.get("original_transient") or "")
                    dialog.tk.call("wm", "transient", dialog._w, original_transient)
                    dialog.deiconify()
                self.root.lift()
                if not destroyed and self._window_is_alive(dialog):
                    dialog.lift()
                    dialog.focus_force()
                else:
                    self.root.focus_force()
            except Exception:
                pass
            self._workspace_reveal_root_state = None
            runtime_log(f"workspace reveal restored window={key}")
        elif not other_active and bool(getattr(self, "_closing", False)):
            self._workspace_reveal_root_state = None

    @staticmethod
    def _window_is_alive(window: tk.Misc | None) -> bool:
        if window is None:
            return False
        try:
            return bool(window.winfo_exists())
        except Exception:
            return False

    def _recover_native_dialog_popup(self) -> bool:
        if not self._native_dialog_active or os.name != "nt":
            return False
        try:
            owner_window = (
                self._native_dialog_restore_window
                if self._window_is_alive(self._native_dialog_restore_window)
                else self.root
            )
            owner_hwnd = self._native_window_handle_for(owner_window)
            if owner_hwnd is None:
                return False
            user32 = ctypes.windll.user32
            user32.GetLastActivePopup.argtypes = [wintypes.HWND]
            user32.GetLastActivePopup.restype = wintypes.HWND
            user32.IsWindow.argtypes = [wintypes.HWND]
            user32.IsWindow.restype = wintypes.BOOL
            user32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
            user32.ShowWindow.restype = wintypes.BOOL
            user32.SetActiveWindow.argtypes = [wintypes.HWND]
            user32.SetActiveWindow.restype = wintypes.HWND
            user32.SetWindowPos.argtypes = [
                wintypes.HWND,
                wintypes.HWND,
                ctypes.c_int,
                ctypes.c_int,
                ctypes.c_int,
                ctypes.c_int,
                wintypes.UINT,
            ]
            user32.SetWindowPos.restype = wintypes.BOOL
            user32.BringWindowToTop.argtypes = [wintypes.HWND]
            user32.BringWindowToTop.restype = wintypes.BOOL
            user32.SetForegroundWindow.argtypes = [wintypes.HWND]
            user32.SetForegroundWindow.restype = wintypes.BOOL
            user32.GetWindow.argtypes = [wintypes.HWND, wintypes.UINT]
            user32.GetWindow.restype = wintypes.HWND
            popup_hwnd = int(user32.GetLastActivePopup(wintypes.HWND(owner_hwnd)) or 0)
            if not popup_hwnd or popup_hwnd == int(owner_hwnd):
                popup_hwnd = int(user32.GetWindow(wintypes.HWND(owner_hwnd), 6) or 0)
            if not popup_hwnd or popup_hwnd == int(owner_hwnd) or not bool(user32.IsWindow(popup_hwnd)):
                return False
            user32.ShowWindow(wintypes.HWND(popup_hwnd), SW_RESTORE)
            user32.ShowWindow(wintypes.HWND(popup_hwnd), SW_SHOW)
            try:
                user32.SetWindowPos(
                    wintypes.HWND(popup_hwnd),
                    wintypes.HWND(0),
                    0,
                    0,
                    0,
                    0,
                    SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW,
                )
            except Exception:
                pass
            user32.BringWindowToTop(wintypes.HWND(popup_hwnd))
            user32.SetActiveWindow(wintypes.HWND(popup_hwnd))
            user32.SetForegroundWindow(wintypes.HWND(popup_hwnd))
            runtime_log(f"native dialog popup restored hwnd={popup_hwnd}")
            return True
        except Exception:
            runtime_log("native dialog popup restore failed")
            runtime_log(traceback.format_exc().rstrip())
            return False

    def _restore_active_modal_window(self, preferred: tk.Misc | None = None) -> None:
        if self._recover_native_dialog_popup():
            return
        target = preferred if self._window_is_alive(preferred) else None
        if target is None:
            target = self._active_application_modal_dialog()
        if target is None:
            try:
                grab_widget = self.root.grab_current()
            except Exception:
                grab_widget = None
            if self._window_is_alive(grab_widget):
                try:
                    target = grab_widget.winfo_toplevel()
                except Exception:
                    target = grab_widget
        if target is None:
            target = self.root
        if not self._window_is_alive(target):
            return
        try:
            state = str(target.state())
            if state in {"iconic", "withdrawn"}:
                target.deiconify()
            target.lift()
            target.focus_force()
        except Exception:
            pass

    def _restore_after_native_dialog(
        self,
        restore_window: tk.Misc,
        previous_grab: tk.Misc | None,
        previous_grab_status: str,
    ) -> None:
        if self._window_is_alive(previous_grab):
            try:
                if previous_grab_status == "global":
                    previous_grab.grab_set_global()
                else:
                    previous_grab.grab_set()
            except Exception:
                pass
        self._restore_active_modal_window(restore_window)

    def _begin_native_popup(self) -> bool:
        """Minimize the main page for a native popup opened from it."""
        if self._auto_minimized_dialogs:
            return False
        try:
            root_state = str(self.root.state())
        except Exception:
            root_state = "normal"
        if root_state in {"iconic", "withdrawn"}:
            return False
        self._auto_minimized_root_state = root_state
        self._auto_minimized_dialogs.add("__native_popup__")
        try:
            self.root.iconify()
        except Exception:
            self._auto_minimized_dialogs.discard("__native_popup__")
            return False
        return True

    def _end_native_popup(self, started: bool) -> None:
        if not started:
            return
        self._auto_minimized_dialogs.discard("__native_popup__")
        try:
            self.root.after_idle(self._restore_root_after_dialogs_close)
        except Exception:
            self._restore_root_after_dialogs_close()

    def _run_native_messagebox(
        self,
        callback: Callable[..., Any],
        *args: Any,
        **kwargs: Any,
    ) -> Any:
        started = self._begin_native_popup()
        try:
            return callback(*args, **kwargs)
        finally:
            self._end_native_popup(started)

    def _run_native_file_dialog(
        self,
        chooser: Callable[..., Any],
        **kwargs: Any,
    ) -> Any:
        requested_parent = kwargs.pop("parent", None)
        restore_window = requested_parent if self._window_is_alive(requested_parent) else self.root
        reveal_state = getattr(self, "_workspace_reveal_dialogs", {}).get(
            self._drop_window_key(restore_window),
            {},
        )
        chooser_parent = restore_window if restore_window is not self.root else self.root
        native_popup_started = False
        try:
            previous_grab = self.root.grab_current()
        except Exception:
            previous_grab = None
        previous_grab_status = ""
        if self._window_is_alive(previous_grab):
            try:
                previous_grab_status = str(previous_grab.grab_status() or "")
            except Exception:
                previous_grab_status = "local"
            try:
                previous_grab.grab_release()
            except Exception:
                pass
        restore_topmost: bool | None = None
        if restore_window is not self.root and self._window_is_alive(restore_window):
            try:
                restore_topmost = bool(restore_window.attributes("-topmost"))
                if restore_topmost:
                    # The Windows picker is modal to this popup. Temporarily
                    # remove the popup's application-level topmost flag so the
                    # native child always paints above it.
                    restore_window.attributes("-topmost", False)
                    restore_window.update_idletasks()
            except Exception:
                restore_topmost = None
        self._native_dialog_active = True
        self._native_dialog_restore_window = restore_window
        runtime_log(
            f"native dialog begin chooser={getattr(chooser, '__name__', type(chooser).__name__)} "
            f"owner={self._drop_window_key(chooser_parent)} "
            f"restore={self._drop_window_key(restore_window)}"
        )
        try:
            self._restore_active_modal_window(restore_window)
            self.root.update_idletasks()
            native_popup_started = self._begin_native_popup()
            return chooser(parent=chooser_parent, **kwargs)
        finally:
            self._native_dialog_active = False
            self._native_dialog_restore_window = None
            if restore_topmost is not None and self._window_is_alive(restore_window):
                try:
                    restore_window.attributes("-topmost", restore_topmost)
                except Exception:
                    pass
            self._restore_after_native_dialog(
                restore_window,
                previous_grab,
                previous_grab_status,
            )
            self._end_native_popup(native_popup_started)
            try:
                self.root.after_idle(
                    lambda window=restore_window, grab=previous_grab, status=previous_grab_status: (
                        self._restore_after_native_dialog(window, grab, status)
                    )
                )
            except Exception:
                pass
            runtime_log("native dialog end")

    def _ask_native_open_filename(self, **kwargs: Any) -> str:
        if filedialog is None:
            return ""
        return str(
            self._run_native_file_dialog(
                filedialog.askopenfilename,
                **kwargs,
            )
            or ""
        )

    def _ask_native_open_filenames(self, **kwargs: Any) -> tuple[str, ...]:
        if filedialog is None:
            return tuple()
        result = self._run_native_file_dialog(
            filedialog.askopenfilenames,
            **kwargs,
        )
        if not result:
            return tuple()
        if isinstance(result, (tuple, list)):
            return tuple(str(item) for item in result)
        try:
            return tuple(str(item) for item in self.root.tk.splitlist(result))
        except Exception:
            return (str(result),)

    def _ask_native_saveas_filename(self, **kwargs: Any) -> str:
        if filedialog is None:
            return ""
        return str(
            self._run_native_file_dialog(
                filedialog.asksaveasfilename,
                **kwargs,
            )
            or ""
        )

    def _ask_native_directory(self, **kwargs: Any) -> str:
        if filedialog is None:
            return ""
        return str(
            self._run_native_file_dialog(
                filedialog.askdirectory,
                **kwargs,
            )
            or ""
        )

    def _cache_startup_prompt_is_snoozed(self) -> bool:
        raw_value = str(self.cache_prompt_snooze_until_utc or "").strip()
        if not raw_value:
            return False
        try:
            snooze_until = datetime.strptime(raw_value, "%Y-%m-%d %H:%M:%SZ").replace(
                tzinfo=timezone.utc
            )
        except Exception:
            self.cache_prompt_snooze_until_utc = ""
            self._save_ui_settings()
            return False
        if datetime.now(timezone.utc) < snooze_until:
            return True
        self.cache_prompt_snooze_until_utc = ""
        self._save_ui_settings()
        return False

    def _snooze_cache_startup_prompt(self) -> None:
        snooze_until = datetime.now(timezone.utc) + timedelta(
            days=CACHE_STARTUP_PROMPT_SNOOZE_DAYS
        )
        self.cache_prompt_snooze_until_utc = snooze_until.strftime("%Y-%m-%d %H:%M:%SZ")
        self._save_ui_settings()

    def _show_startup_cache_prompt_if_needed(self) -> None:
        # Cache loading is user initiated from Cache Management. This legacy
        # hook remains harmless for old launch paths but never opens a dialog.
        self._startup_cache_prompt_complete = True

    def _cache_source_kind_text(self, source_kind: str) -> str:
        labels = {
            "arc": self.tr("ARC", "ARC"),
            "folder": self.tr("Folder", "文件夹"),
            "drop_inputs": self.tr("Files", "文件"),
            "project": self.tr("Project", "工程"),
        }
        return labels.get(source_kind, source_kind or self.tr("Project", "工程"))

    def _cache_view_kind_text(self, view_kind: str) -> str:
        if view_kind == "actual_source":
            return self.tr("Actual source view", "真实源视图")
        return self.tr("Editing cache", "编辑缓存")

    def open_history_paths_dialog(self) -> None:
        if self._history_paths_dialog_open:
            return
        self._history_paths_dialog_open = True
        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("History Paths", "历史路径"))
        dialog.transient(self.root)
        dialog.resizable(True, True)
        dialog.minsize(820, 440)
        path_by_iid: dict[str, str] = {}
        details_var = tk.StringVar()

        def close_dialog() -> None:
            self._history_paths_dialog_open = False
            self._history_paths_dialog_refresh = None
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()
            self._restore_root_after_application_modal_close()

        def selected_path() -> str:
            selection = tree.selection()
            return path_by_iid.get(str(selection[0]), "") if selection else ""

        def refresh() -> None:
            path_by_iid.clear()
            for item_id in tree.get_children():
                tree.delete(item_id)
            for index, path_text in enumerate(self.history_paths):
                path = Path(path_text)
                state = self.tr("Available", "可用") if path.exists() else self.tr("Missing", "已失效")
                kind = (
                    self.tr("Folder", "文件夹")
                    if path.is_dir()
                    else self.tr("ARC", "ARC")
                    if path.suffix.casefold() == ".arc"
                    else self.tr("TXT", "TXT")
                    if path.suffix.casefold() == ".txt"
                    else self.tr("File", "文件")
                )
                item_id = f"path_{index}"
                path_by_iid[item_id] = path_text
                tree.insert("", "end", iid=item_id, values=(kind, state, path_text))
            open_button.configure(state="normal" if path_by_iid else "disabled")
            reveal_button.configure(state="normal" if path_by_iid else "disabled")
            remove_button.configure(state="normal" if path_by_iid else "disabled")
            details_var.set(
                self.tr(
                    f"Only the {HISTORY_PATH_LIMIT} most recent paths are saved. ARC projects, parsed data, snapshots, and edit state are destroyed when the tool exits.",
                    f"这里只保存最近 {HISTORY_PATH_LIMIT} 条路径。ARC 工程、解析数据、快照和编辑状态都会在工具退出时销毁。",
                )
            )

        self._history_paths_dialog_refresh = refresh

        def refresh_selection(*_args: Any) -> None:
            path_text = selected_path()
            if not path_text:
                return
            path = Path(path_text)
            details_var.set(
                self.tr(
                    f"{path_text}\n\n{'Available' if path.exists() else 'Missing'}",
                    f"{path_text}\n\n{'可用' if path.exists() else '已失效'}",
                )
            )

        def open_selected() -> None:
            path_text = selected_path()
            if not path_text:
                return
            path = Path(path_text)
            if not path.exists():
                self.set_status(
                    f"Historical path is no longer available: {path}",
                    f"历史路径已失效：{path}",
                )
                refresh()
                return
            close_dialog()
            if path.is_file() and path.suffix.casefold() == ".arc":
                self.open_arc_from_path(path)
            elif path.is_file() and path.suffix.casefold() == ".txt":
                self._handle_loaded_export_txt(path)
            elif path.is_dir():
                self._handle_loaded_folder(path)
            else:
                self.set_status(
                    f"Historical path is not a supported ARC input: {path}",
                    f"历史路径不是受支持的 ARC 输入：{path}",
                )

        def reveal_selected() -> None:
            path_text = selected_path()
            if not path_text:
                return
            path = Path(path_text)
            target = path if path.is_dir() else path.parent
            try:
                if os.name == "nt":
                    os.startfile(str(target))
                else:
                    webbrowser.open(target.resolve(strict=False).as_uri())
            except Exception as exc:
                self.show_error(str(exc))

        def remove_selected() -> None:
            path_text = selected_path()
            if not path_text:
                return
            self._remove_history_path(path_text)
            refresh()

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill="both", expand=True)
        ttk.Label(
            body,
            text=self.tr(
                "Recent input paths only. This tool never resumes an old ARC project or editing state.",
                "这里只保留最近输入路径。工具不会恢复旧 ARC 工程或编辑状态。",
            ),
            justify="left",
        ).pack(anchor="w")
        table_wrap = ttk.Frame(body)
        table_wrap.pack(fill="both", expand=True, pady=(12, 0))
        table_wrap.columnconfigure(0, weight=1)
        table_wrap.rowconfigure(0, weight=1)
        tree = ttk.Treeview(
            table_wrap,
            columns=("kind", "state", "path"),
            show="headings",
            selectmode="browse",
        )
        tree.heading("kind", text=self.tr("Type", "类型"))
        tree.heading("state", text=self.tr("State", "状态"))
        tree.heading("path", text=self.tr("Path", "路径"))
        tree.column("kind", width=90, minwidth=70, stretch=False)
        tree.column("state", width=90, minwidth=70, stretch=False)
        tree.column("path", width=590, minwidth=280, stretch=True)
        scroll = self._create_themed_scrollbar(table_wrap, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.grid(row=0, column=0, sticky="nsew")
        scroll.grid(row=0, column=1, sticky="ns")
        ttk.Label(body, textvariable=details_var, justify="left", wraplength=760).pack(
            anchor="w", fill="x", pady=(10, 0)
        )
        button_row = ttk.Frame(body)
        button_row.pack(fill="x", pady=(14, 0))
        ttk.Button(button_row, text=self.tr("Close", "关闭"), command=close_dialog).pack(side="right")
        remove_button = ttk.Button(button_row, text=self.tr("Remove", "移除"), command=remove_selected)
        remove_button.pack(side="right", padx=(0, 8))
        reveal_button = ttk.Button(button_row, text=self.tr("Show in Explorer", "在资源管理器中打开"), command=reveal_selected)
        reveal_button.pack(side="right", padx=(0, 8))
        open_button = ttk.Button(button_row, text=self.tr("Open Selected", "打开选中路径"), command=open_selected)
        open_button.pack(side="left")
        tree.bind("<<TreeviewSelect>>", refresh_selection)
        tree.bind("<Double-1>", lambda _event: open_selected())
        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        self._center_dialog(dialog)
        self._apply_toplevel_theme(dialog)
        refresh()
        first_item = tree.get_children()[0] if tree.get_children() else ""
        if first_item:
            tree.selection_set(first_item)
            tree.focus(first_item)
            tree.see(first_item)
            refresh_selection()
        dialog.grab_set()
        dialog.focus_force()

    def open_cache_project_dialog(
        self,
        *,
        startup: bool = False,
        projects: list[dict[str, Any]] | None = None,
    ) -> None:
        if self._cache_project_dialog_open:
            return
        if projects is None:
            projects = discover_cache_projects(self.script_dir)
        if not projects:
            if not startup:
                self.show_warning(
                    self.tr(
                        "No loadable ARC cache project was found.",
                        "当前没有可加载的 ARC 缓存工程。",
                    )
                )
            return
        self._cache_project_dialog_open = True
        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("Cache Management", "缓存管理"))
        dialog.transient(self.root)
        dialog.resizable(True, True)
        dialog.minsize(1120, 600)
        details_var = tk.StringVar()
        project_by_iid: dict[str, dict[str, Any]] = {}

        def close_dialog() -> None:
            self._cache_project_dialog_open = False
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()
            self._restore_root_after_application_modal_close()

        def reset_open_flag(event: Any) -> None:
            if getattr(event, "widget", None) is dialog:
                self._cache_project_dialog_open = False

        def selected_project() -> dict[str, Any] | None:
            selection = tree.selection()
            if not selection:
                return None
            return project_by_iid.get(str(selection[0]))

        def refresh_selection(*_args: Any) -> None:
            project = selected_project()
            if project is None:
                details_var.set(self.tr("Select one cache project.", "请选择一个缓存工程。"))
                load_button.configure(state="disabled")
                return
            root_path = Path(project["project_root"])
            details_var.set(
                self.tr(
                    f"Cache project: {root_path}\nSource: {project['source_display']}",
                    f"缓存工程：{root_path}\n来源：{project['source_display']}",
                )
            )
            load_button.configure(
                state="normal" if project_cache_is_loadable(root_path) else "disabled"
            )

        def load_selected() -> None:
            project = selected_project()
            if project is None:
                return
            project_root = Path(project["project_root"])
            validation_error = project_cache_validation_error(project_root)
            if validation_error:
                self.show_error(
                    self.tr(
                        f"The selected cache project is no longer valid:\n{project_root}\n\n{validation_error}",
                        f"选中的缓存工程已经失效：\n{project_root}\n\n{validation_error}",
                    )
                )
                refresh_selection()
                return
            close_dialog()
            self.load_project(project_root)

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill="both", expand=True)
        ttk.Label(
            body,
            text=self.tr(
                "Cache Management is manual. Load a saved ARC editing cache only when you choose to resume it.",
                "缓存管理只在您手动打开时出现。仅在需要继续编辑时，加载已保存的 ARC 编辑缓存。",
            ),
            justify="left",
        ).pack(anchor="w")

        table_wrap = ttk.Frame(body)
        table_wrap.pack(fill="both", expand=True, pady=(12, 0))
        table_wrap.columnconfigure(0, weight=1)
        table_wrap.rowconfigure(0, weight=1)
        columns = ("name", "view", "source_kind", "files", "updated", "source")
        tree = ttk.Treeview(table_wrap, columns=columns, show="headings", selectmode="browse")
        headings = {
            "name": self.tr("ARC / Project", "ARC / 工程"),
            "view": self.tr("Cache Type", "缓存类型"),
            "source_kind": self.tr("Source Type", "来源类型"),
            "files": self.tr("Files", "文件数"),
            "updated": self.tr("Updated", "更新时间"),
            "source": self.tr("Original Source", "原始来源"),
        }
        widths = {
            "name": 190,
            "view": 130,
            "source_kind": 95,
            "files": 75,
            "updated": 130,
            "source": 430,
        }
        for column in columns:
            tree.heading(column, text=headings[column])
            tree.column(column, width=widths[column], minwidth=60, stretch=column == "source")
        scroll = self._create_themed_scrollbar(table_wrap, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.grid(row=0, column=0, sticky="nsew")
        scroll.grid(row=0, column=1, sticky="ns")
        for index, project in enumerate(projects):
            iid = f"cache_{index}"
            project_by_iid[iid] = project
            tree.insert(
                "",
                "end",
                iid=iid,
                values=(
                    project["project_name"],
                    self._cache_view_kind_text(str(project["view_kind"])),
                    self._cache_source_kind_text(str(project["source_kind"])),
                    int(project["entry_count"]),
                    project["updated_local"],
                    project["source_display"],
                ),
            )

        ttk.Label(
            body,
            textvariable=details_var,
            justify="left",
            wraplength=1040,
        ).pack(anchor="w", fill="x", pady=(10, 0))
        button_row = ttk.Frame(body)
        button_row.pack(fill="x", pady=(14, 0))
        ttk.Button(
            button_row,
            text=self.tr("Close", "关闭"),
            command=close_dialog,
        ).pack(side="right")
        load_button = ttk.Button(
            button_row,
            text=self.tr("Load Selected Cache", "确认加载选中缓存"),
            command=load_selected,
            state="disabled",
        )
        load_button.pack(side="right", padx=(0, 8))
        tree.bind("<<TreeviewSelect>>", refresh_selection)
        tree.bind("<Double-1>", lambda _event: load_selected())
        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        dialog.bind("<Destroy>", reset_open_flag, add="+")
        self._center_dialog(dialog)
        self._apply_toplevel_theme(dialog)
        first_iid = tree.get_children()[0] if tree.get_children() else ""
        if first_iid:
            tree.selection_set(first_iid)
            tree.focus(first_iid)
            tree.see(first_iid)
        refresh_selection()
        dialog.grab_set()
        dialog.focus_force()

    def _start_directory_format_conversion_worker(
        self,
        input_root: Path,
        output_root: Path,
        *,
        overwrite_existing: bool,
        include_subdirectories: bool,
        preserve_output_structure: bool,
    ) -> None:
        def task() -> dict[str, Any]:
            return convert_supported_files_in_directory(
                input_root,
                output_root,
                self.script_dir,
                progress=self.thread_log,
                overwrite_existing=overwrite_existing,
                include_subdirectories=include_subdirectories,
                preserve_output_structure=preserve_output_structure,
            )

        self.start_worker(
            self.tr("Converting supported files...", "正在转换支持的文件..."),
            task,
        )

    def _start_quick_file_format_conversion_worker(
        self,
        source_paths: list[Path],
        *,
        overwrite_existing: bool,
    ) -> None:
        def task() -> dict[str, Any]:
            return quick_convert_supported_files(
                source_paths,
                self.script_dir,
                progress=self.thread_log,
                overwrite_existing=overwrite_existing,
            )

        self.start_worker(
            self.tr("Quick converting dropped files...", "正在快速转换拖入的文件..."),
            task,
        )

    def _continue_quick_file_format_conversion_after_preflight(
        self,
        preflight: dict[str, Any],
    ) -> None:
        """Finish quick-drop preflight after its worker has exited."""
        if self._closing:
            return
        if self.worker is not None and self.worker.is_alive():
            self.root.after(
                25,
                lambda data=dict(preflight): self._continue_quick_file_format_conversion_after_preflight(data),
            )
            return
        self.worker = None
        self._active_worker_label = ""

        source_paths = [
            Path(str(path))
            for path in list(preflight.get("source_paths") or [])
            if str(path).strip()
        ]
        recognized_count = int(preflight.get("recognized_count", 0) or 0)
        if not source_paths or recognized_count <= 0:
            self.show_warning(
                self.tr(
                    "Quick Convert found no supported source files in the dropped selection.",
                    "快速转换没有在拖入内容中找到可转换的源文件。",
                )
            )
            return

        input_target_conflicts = [
            item
            for item in list(preflight.get("input_target_conflicts") or [])
            if isinstance(item, dict)
        ]
        if input_target_conflicts:
            preview = "\n".join(
                f"- {item.get('source_path', '')} -> {item.get('target_path', '')}"
                for item in input_target_conflicts[:8]
            )
            self.show_error(
                self.tr(
                    "Quick Convert stopped because one dropped file would overwrite another dropped source file. "
                    "Drop only one direction for each same-name file pair.\n\n"
                    f"{preview}",
                    "快速转换已停止：拖入文件中存在会覆盖另一份拖入源文件的目标。"
                    "同名文件对请一次只拖入一个方向。\n\n"
                    f"{preview}",
                )
            )
            return

        conflicts = [
            item
            for item in list(preflight.get("existing_targets") or [])
            if isinstance(item, dict)
        ]
        overwrite_existing = False
        if conflicts and messagebox is not None:
            preview_paths = [
                str(item.get("target_path") or "")
                for item in conflicts[:8]
            ]
            preview = "\n".join(f"- {path}" for path in preview_paths if path)
            remaining_count = len(conflicts) - len(preview_paths)
            preview_en = preview
            preview_zh = preview
            if remaining_count > 0:
                preview_en += f"\n... and {remaining_count} more target(s)"
                preview_zh += f"\n... 其余 {remaining_count} 个目标"
            overwrite_existing = bool(
                self._run_native_messagebox(
                    messagebox.askyesno,
                    self.tr("Quick Convert Existing Files", "快速转换发现同名文件"),
                    self.tr(
                        f"{len(conflicts)} same-name output target(s) already exist:\n\n"
                        f"{preview_en}\n\n"
                        "Overwrite those existing targets?\n\n"
                        "Yes: overwrite the same-name targets.\n"
                        "No: keep them unchanged and skip them.",
                        f"已发现 {len(conflicts)} 个同名输出目标：\n\n"
                        f"{preview_zh}\n\n"
                        "是否覆盖这些同名目标？\n\n"
                        "是：覆盖同名目标。\n"
                        "否：保留原文件并跳过。",
                    ),
                    icon="warning",
                    default="no",
                )
            )

        self._start_quick_file_format_conversion_worker(
            source_paths,
            overwrite_existing=overwrite_existing,
        )

    def _continue_directory_format_conversion_after_preflight(
        self,
        preflight: dict[str, Any],
    ) -> None:
        """Ask about existing targets only after the preflight worker has stopped."""
        if self._closing:
            return
        if self.worker is not None and self.worker.is_alive():
            self.root.after(
                25,
                lambda data=dict(preflight): self._continue_directory_format_conversion_after_preflight(data),
            )
            return
        self.worker = None
        self._active_worker_label = ""

        input_root = Path(str(preflight.get("input_root") or ""))
        output_root = Path(str(preflight.get("output_root") or ""))
        include_subdirectories = bool(preflight.get("include_subdirectories", True))
        preserve_output_structure = bool(preflight.get("preserve_output_structure", True))
        duplicate_targets = [
            item
            for item in list(preflight.get("duplicate_targets") or [])
            if isinstance(item, dict)
        ]
        if duplicate_targets:
            preview = "\n".join(
                f"- {item.get('source_relative_path', '')} -> {item.get('target_relative_path', '')}"
                for item in duplicate_targets[:8]
            )
            self.show_error(
                self.tr(
                    "More than one source file targets the same output file. "
                    "Turn on Preserve Source Folder Structure or rename the source files.\n\n"
                    f"{preview}",
                    "多个源文件会写入同一个输出文件。请勾选“输出目录保留源目录文件夹结构”，"
                    "或先重命名源文件。\n\n"
                    f"{preview}",
                )
            )
            return
        conflicts = [
            item
            for item in list(preflight.get("existing_targets") or [])
            if isinstance(item, dict)
        ]
        overwrite_existing = False
        if conflicts and messagebox is not None:
            preview_limit = 8
            preview_paths = [
                str(item.get("target_relative_path") or item.get("target_path") or "")
                for item in conflicts[:preview_limit]
            ]
            preview = "\n".join(f"- {path}" for path in preview_paths if path)
            remaining_count = len(conflicts) - len(preview_paths)
            preview_en = preview
            preview_zh = preview
            if remaining_count > 0:
                preview_en += f"\n... and {remaining_count} more target(s)"
                preview_zh += f"\n... 其余 {remaining_count} 个目标"
            overwrite_existing = bool(
                self._run_native_messagebox(
                    messagebox.askyesno,
                    self.tr("Existing Output Files", "发现同名输出文件"),
                    self.tr(
                        f"{len(conflicts)} same-name output target(s) already exist:\n\n"
                        f"{preview_en}\n\n"
                        "Overwrite those existing targets?\n\n"
                        "Yes: overwrite the same-name targets.\n"
                        "No: keep them unchanged and skip them.",
                        f"输出目录中已发现 {len(conflicts)} 个同名目标：\n\n"
                        f"{preview_zh}\n\n"
                        "是否覆盖这些同名目标？\n\n"
                        "是：覆盖同名目标。\n"
                        "否：保留原文件并跳过。",
                    ),
                    icon="warning",
                    default="no",
                )
            )

        self._start_directory_format_conversion_worker(
            input_root,
            output_root,
            overwrite_existing=overwrite_existing,
            include_subdirectories=include_subdirectories,
            preserve_output_structure=preserve_output_structure,
        )

    def open_directory_format_conversion_dialog(self) -> None:
        """Open the standalone reversible-format directory conversion tool."""
        if tk is None or ttk is None or filedialog is None:
            return
        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("File Format Conversion", "文件格式转换"))
        dialog.transient(self.root)
        dialog.resizable(False, False)
        dialog.minsize(780, 340)
        input_dir_var = tk.StringVar()
        output_dir_var = tk.StringVar()
        include_subdirectories_var = tk.BooleanVar(value=True)
        preserve_output_structure_var = tk.BooleanVar(value=True)

        body = ttk.Frame(dialog, padding=16)
        body.pack(fill="both", expand=True)
        ttk.Label(
            body,
            text=self.tr("File Format Conversion", "文件格式转换"),
            font=(UI_FONT_FAMILY, 12, "bold"),
        ).pack(anchor="w")
        ttk.Label(
            body,
            text=self.tr(
                "Auto-detect and convert both directions: XFS <-> XML    TEX <-> DDS    SPC <-> SPC folder",
                "自动识别并双向转换：XFS <-> XML    TEX <-> DDS    SPC <-> SPC 文件夹",
            ),
            justify="left",
            wraplength=740,
        ).pack(anchor="w", pady=(7, 0))
        ttk.Label(
            body,
            text=self.tr(
                "Parsed files require the original file or a parsed TXT template. Repacking with parsed files alone is unreliable, so parsed files alone are not supported for repacking.",
                "解析文件需要原始文件或者解析 TXT 做模板。只有解析文件时重打包不可靠，因此不支持只有解析文件重打包",
            ),
            justify="left",
            wraplength=740,
            style="ConversionNotice.TLabel",
        ).pack(anchor="w", pady=(8, 0))

        fields = ttk.Frame(body)
        fields.pack(fill="x", pady=(18, 0))
        fields.columnconfigure(1, weight=1)

        def choose_input_dir() -> None:
            selected = self._ask_native_directory(
                title=self.tr("Select Input Directory", "选择输入目录"),
                mustexist=True,
                parent=dialog,
            )
            if selected:
                input_dir_var.set(selected)

        def choose_output_dir() -> None:
            selected = self._ask_native_directory(
                title=self.tr("Select Output Directory", "选择输出目录"),
                mustexist=True,
                parent=dialog,
            )
            if selected:
                output_dir_var.set(selected)

        for row, (label_en, label_zh, variable, command) in enumerate(
            (
                ("Input Directory", "输入目录", input_dir_var, choose_input_dir),
                ("Output Directory", "输出目录", output_dir_var, choose_output_dir),
            )
        ):
            pady = (0, 0) if row == 0 else (10, 0)
            ttk.Label(
                fields,
                text=self.tr(label_en, label_zh),
                font=(UI_FONT_FAMILY, 10, "bold"),
            ).grid(row=row, column=0, sticky="w", padx=(0, 10), pady=pady)
            ttk.Entry(fields, textvariable=variable).grid(
                row=row,
                column=1,
                sticky="ew",
                pady=pady,
            )
            ttk.Button(
                fields,
                text=self.tr("Select", "选择"),
                command=command,
            ).grid(row=row, column=2, padx=(8, 0), pady=pady)

        options = ttk.Frame(body)
        options.pack(fill="x", pady=(14, 0))
        ttk.Checkbutton(
            options,
            text=self.tr(
                "Scan all files in input subfolders; clear to scan input directory only",
                "输入目录扫描所有子文件，取消勾选只扫描输入目录一层",
            ),
            variable=include_subdirectories_var,
            style="Tick.TCheckbutton",
        ).pack(anchor="w")
        ttk.Checkbutton(
            options,
            text=self.tr(
                "Preserve source folder structure in the output directory",
                "输出目录保留源目录文件夹结构",
            ),
            variable=preserve_output_structure_var,
            style="Tick.TCheckbutton",
        ).pack(anchor="w", pady=(7, 0))

        def start_conversion() -> None:
            input_text = str(input_dir_var.get()).strip()
            output_text = str(output_dir_var.get()).strip()
            if not input_text or not Path(input_text).is_dir():
                self.show_error(self.tr("Select a valid input directory.", "请选择有效的输入目录。"))
                return
            if not output_text:
                self.show_error(self.tr("Select an output directory.", "请选择输出目录。"))
                return
            output_root = Path(output_text)
            if output_root.exists() and not output_root.is_dir():
                self.show_error(self.tr("Output path must be a directory.", "输出路径必须是文件夹。"))
                return
            input_root = Path(input_text)
            include_subdirectories = bool(include_subdirectories_var.get())
            preserve_output_structure = bool(preserve_output_structure_var.get())
            if _directory_conversion_roots_are_same(input_root, output_root):
                self.show_error(
                    self.tr(
                        "Input and output directories cannot be the same directory.",
                        "输入目录和输出目录不能是同一文件夹。",
                    )
                )
                return
            dialog.destroy()

            def task() -> dict[str, Any]:
                return preflight_directory_format_conversion(
                    input_root,
                    output_root,
                    include_subdirectories=include_subdirectories,
                    preserve_output_structure=preserve_output_structure,
                )

            self.start_worker(
                self.tr("Checking existing output files...", "正在检查已有输出文件..."),
                task,
            )

        def start_quick_conversion(paths: list[Path]) -> None:
            source_paths = [Path(path) for path in paths if Path(path).is_file()]
            if not source_paths:
                self.show_error(
                    self.tr(
                        "Quick Convert accepts files only.",
                        "快速转换只接收文件。",
                    )
                )
                return
            dialog.destroy()

            def task() -> dict[str, Any]:
                return preflight_quick_file_format_conversion(source_paths)

            self.start_worker(
                self.tr("Checking quick conversion targets...", "正在检查快速转换目标..."),
                task,
            )

