    def _conversion_row_capability(
        self,
        mode_key: str | None,
        source_path: Path,
        parsed_available: bool,
    ) -> str:
        if mode_key not in CONVERSION_SPECS:
            return "neutral"
        try:
            source_magic = read_file_magic(source_path)
        except Exception:
            return "read_only" if parsed_available else "neutral"
        if source_magic == FORMAT_MAGIC_SPC:
            if mode_key == "known_formats" and parsed_available:
                return "writable"
            return "read_only" if parsed_available else "neutral"
        if not parsed_available:
            return "neutral"
        if source_magic == FORMAT_MAGIC_TEX and mode_key in {"tex_dds", "known_formats"}:
            return "writable"
        if source_magic == FORMAT_MAGIC_XFS and mode_key in {"xml", "known_formats"}:
            return "writable"
        if source_magic == FORMAT_MAGIC_LMT and mode_key in {"known_formats", "lmt_gltf_handoff"}:
            return "unverified"
        if mode_key == "tex_dds":
            return "writable" if source_magic == FORMAT_MAGIC_TEX else "read_only"
        if mode_key == "xml":
            return "writable" if source_magic == FORMAT_MAGIC_XFS else "read_only"
        return "read_only"

    def _conversion_capability_annotation(self, capability: str) -> str:
        if capability == "writable":
            return self.tr(
                "(Parse + repack)",
                "（能解析，能重打包生效）",
            )
        if capability == "read_only":
            return self.tr(
                "(Unparsed; original file retained)",
                "（未解析，仅保留原版文件）",
            )
        if capability == "unverified":
            return self.tr(
                "(Can parse, but can only be exported for another file format)",
                "（能解析，但只能导出给其它文件）",
            )
        if capability == "blocked":
            return self.tr("(Parsing disabled)", "（禁止解析）")
        return ""

    def _conversion_capability_tree_tag(self, capability: str) -> str:
        if capability == "writable":
            return "conversion_writable"
        if capability == "unverified":
            return "conversion_unverified"
        if capability in {"read_only", "blocked"}:
            return "conversion_blocked"
        return ""

