    def open_batch_extract_arc_dialog(self) -> None:
        if filedialog is None:
            return
        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("Batch Extract ARC", "批量解包 ARC"))
        dialog.transient(self.root)
        dialog.resizable(True, False)
        dialog.minsize(1040, 1)
        self._enable_dialog_workspace_reveal(dialog)
        arc_dir_var = tk.StringVar()
        output_dir_var = tk.StringVar()

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill="x")
        batch_copy_font = (UI_FONT_FAMILY, 10)
        batch_copy_bold_font = (UI_FONT_FAMILY, 10, "bold")
        ttk.Label(
            body,
            text=self.tr(
                "Select an ARC folder and an output folder. Batch Extract creates parsed workspaces and one TXT for each ARC.",
                "请选择 ARC 所在目录和输出目录。\n只批量解包解析文件，每个 ARC 都有自己的 TXT 文件。",
            ),
            justify="left",
            font=batch_copy_bold_font,
            wraplength=930,
        ).pack(anchor="w")
        ttk.Label(
            body,
            text=self.tr(
                "Output folder:\n"
                "0001 - first.arc/\n"
                f"0001 - first.arc{BATCH_ARC_MANIFEST_FILE_NAME_SUFFIX}\n"
                "0002 - second.arc/\n"
                f"0002 - second.arc{BATCH_ARC_MANIFEST_FILE_NAME_SUFFIX}",
                "输出目录：\n"
                "0001 - 第一个.arc 文件夹\n"
                f"0001 - 第一个.arc{BATCH_ARC_MANIFEST_FILE_NAME_SUFFIX}\n"
                "0002 - 第二个.arc 文件夹\n"
                f"0002 - 第二个.arc{BATCH_ARC_MANIFEST_FILE_NAME_SUFFIX}",
            ),
            justify="left",
            font=batch_copy_font,
            wraplength=930,
        ).pack(anchor="w", pady=(10, 0))
        ttk.Label(
            body,
            text=self.tr(
                "Do not delete TXT files. Without them only Pack All ARC remains, and its in-game compatibility is unverified.\n\n"
                "Source files -> parsed files: supported formats can write back.\n"
                "TEX -> DDS\n"
                "XFS -> XML\n"
                "Single SPC file -> same-named SPC folder with metadata and audio\n"
                "Edit audio only. Do not edit metadata.",
                "TXT 文件别删，不然只能走全部打包模式，进游戏兼容性未验证\n\n"
                "源文件 -> 解析文件，能解析能回写\n"
                "TEX -> DDS\n"
                "XFS -> XML\n"
                "SPC 格式单文件 -> SPC 名的文件夹，文件夹内分 metadata 和 audio\n"
                "改动 audio，别碰 metadata",
            ),
            justify="left",
            font=batch_copy_font,
            wraplength=930,
        ).pack(anchor="w", pady=(10, 0))

        fields = ttk.Frame(body)
        fields.pack(fill="x", pady=(18, 0))
        fields.columnconfigure(1, weight=1)

        def choose_arc_dir() -> None:
            selected = self._ask_native_directory(
                title=self.tr("Select ARC Folder", "选择 ARC 目录"),
                mustexist=True,
                parent=dialog,
            )
            if selected:
                arc_dir_var.set(selected)

        def choose_output_dir() -> None:
            selected = self._ask_native_directory(
                title=self.tr("Select Batch Output Folder", "选择批量输出目录"),
                mustexist=True,
                parent=dialog,
            )
            if selected:
                output_dir_var.set(selected)

        ttk.Label(fields, text=self.tr("ARC Folder", "ARC 目录"), font=batch_copy_font).grid(row=0, column=0, sticky="w", padx=(0, 10))
        ttk.Entry(fields, textvariable=arc_dir_var).grid(row=0, column=1, sticky="ew")
        ttk.Button(fields, text=self.tr("Browse", "浏览"), command=choose_arc_dir).grid(row=0, column=2, padx=(8, 0))
        ttk.Label(fields, text=self.tr("Output Folder", "输出目录"), font=batch_copy_font).grid(row=1, column=0, sticky="w", padx=(0, 10), pady=(10, 0))
        ttk.Entry(fields, textvariable=output_dir_var).grid(row=1, column=1, sticky="ew", pady=(10, 0))
        ttk.Button(fields, text=self.tr("Browse", "浏览"), command=choose_output_dir).grid(row=1, column=2, padx=(8, 0), pady=(10, 0))

        def start_batch_extract() -> None:
            arc_root = Path(arc_dir_var.get().strip())
            output_root = Path(output_dir_var.get().strip())
            if not arc_root.exists() or not arc_root.is_dir():
                self.show_error(self.tr("Select a valid ARC folder.", "请选择有效的 ARC 目录。"))
                return
            if not output_root.exists() or not output_root.is_dir():
                self.show_error(self.tr("Select a valid output folder.", "请选择有效的输出目录。"))
                return
            arc_paths = sorted(
                (path for path in arc_root.rglob("*") if path.is_file() and path.suffix.casefold() == ".arc"),
                key=lambda path: path.as_posix().casefold(),
            )
            if self._arc_files_have_mrl_or_texture_resources(arc_paths):
                self._show_mrl_texture_freedom_notice(
                    parent=dialog,
                    context_en="Batch Extract detected ARC files containing MRL or TEX/DDS texture resources.",
                    context_zh="批量解包检测到 ARC 中包含 MRL 或 TEX/DDS 贴图资源。",
                )
            occupied = [
                str(path)
                for path in (
                    output_root / BATCH_SOURCE_DIR_NAME,
                    output_root / BATCH_PARSED_DIR_NAME,
                    *_batch_generated_workspace_paths(output_root),
                    output_root / BATCH_MANIFEST_FILE_NAME,
                    *find_per_arc_batch_manifest_paths_in_folder(output_root),
                )
                if path.exists()
            ]
            if occupied and not self._ask_batch_collision_continue(
                parent=dialog,
                title_en="Replace Existing Batch Output?",
                title_zh="替换已有批量输出？",
                message_en=(
                    "Generated batch output already exists at this location. Continuing clears the listed numbered ARC folders and rewrites every matching per-ARC TXT. Cancel or close this window to keep them unchanged."
                ),
                message_zh=(
                    "此位置已经存在批量生成结果。继续会清空下列编号 ARC 文件夹，并重写每个 ARC 对应的 TXT；取消或关闭此窗口会保留原内容。"
                ),
                collisions=occupied,
            ):
                return
            dialog.destroy()

            def task() -> dict[str, Any]:
                return batch_extract_re6_arcs(
                    arc_root,
                    output_root,
                    self.script_dir,
                    overwrite_existing=True,
                    progress=self.thread_log,
                )

            self.start_worker(
                self.tr("Batch extracting ARC files...", "正在批量解包 ARC..."),
                task,
            )

        button_row = ttk.Frame(body)
        button_row.pack(fill="x", pady=(20, 0))
        ttk.Button(button_row, text=self.tr("Cancel", "取消"), command=dialog.destroy).pack(side="right")
        ttk.Button(
            button_row,
            text=self.tr("Start Batch Extract", "开始批量解包"),
            command=start_batch_extract,
        ).pack(side="right", padx=(0, 8))
        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)
        self._center_dialog(dialog)
        dialog.grab_set()
        dialog.focus_force()

