    def _show_custom_batch_preflight_issues(self, preflight: dict[str, Any]) -> None:
        detail_lines: list[str] = []
        for item in preflight.get("issues", []):
            if not isinstance(item, dict):
                continue
            detail_lines.append(f"[BLOCKED] {item.get('path', '')}")
            detail_lines.append(f"  {item.get('error', '')}")
        self._show_custom_batch_details_dialog(
            title_en="No-TXT Pure Custom Batch Preflight",
            title_zh="无 TXT 纯自定义批量打包预检查",
            intro_en="No-TXT Pure Custom Batch has not started. Red rows are unparsed original-format files. Yellow LMT intermediates are blocked earlier and must be replaced by exact-path original LMT files before this preflight. DDS/XML/SPC use only their dedicated writeback paths.",
            intro_zh="无 TXT 纯自定义批量打包尚未开始。红色条目表示未解析、保留原版格式文件；黄色 LMT 中间产物会在此前被硬拦截，必须按完整相对路径恢复原版 LMT 后才能进入本预检查。DDS/XML/SPC 只走各自专用回写链。",
            detail_lines=detail_lines,
        )

    def _collect_yellow_artifacts_for_input_paths(
        self,
        input_paths: list[Path],
    ) -> list[dict[str, Any]]:
        artifacts: list[dict[str, Any]] = []
        seen: set[str] = set()
        for input_path in input_paths:
            if not input_path.is_dir():
                continue
            for item in _custom_batch_non_writeback_parsed_artifacts(input_path):
                path_key = os.path.normcase(str(item.get("path") or ""))
                if not path_key or path_key in seen:
                    continue
                seen.add(path_key)
                artifacts.append(item)
        return artifacts

    @staticmethod
    def _standalone_yellow_input_paths(input_paths: list[Path]) -> list[Path]:
        return [
            path
            for path in input_paths
            if path.is_file()
            and path.suffix.lower() in {".json", ".txt", ".gltf", ".glb"}
            and ".lmt." in path.name.casefold()
        ]

    def _block_standalone_yellow_inputs(self, input_paths: list[Path]) -> bool:
        blocked = self._standalone_yellow_input_paths(input_paths)
        if not blocked:
            return False
        preview = "\n".join(f"- {path}" for path in blocked[:20])
        self.show_error(self.tr(
            "Individual LMT JSON/TXT/GLTF/GLB intermediates cannot be imported because they do not carry a trustworthy full ARC-relative path. Import the containing ARC folder with its complete hierarchy, or import a real .lmt file instead.\n\n" + preview,
            "不能单独导入 LMT JSON/TXT/GLTF/GLB 中间产物，因为单个文件没有可信的完整 ARC 相对路径。请导入保留完整层级的 ARC 文件夹，或直接导入真正的 .lmt 文件。\n\n" + preview,
        ))
        return True

    def _confirm_custom_spc_folder_inputs(
        self,
        input_paths: list[Path],
        *,
        parent: tk.Misc | None = None,
    ) -> tuple[bool, bool]:
        """Return (continue, unsafe-author-override) for custom SPC folders."""
        bundles = _collect_custom_spc_input_bundles(input_paths)
        unsafe = [
            (bundle, relative)
            for bundle, relative in bundles
            if not _custom_spc_bundle_is_self_contained(bundle)
        ]
        if not unsafe:
            return True, False
        if messagebox is None:
            return True, True
        preview = "\n".join(
            f"- {bundle} -> {relative.as_posix()}"
            for bundle, relative in unsafe[:20]
        )
        options: dict[str, Any] = {"icon": "warning", "default": "no"}
        if parent is not None:
            options["parent"] = parent
        first = self._run_native_messagebox(
            messagebox.askyesno,
            self.tr("Incomplete Custom SPC Folder", "自定义 SPC 文件夹不完整"),
            self.tr(
                "One or more .SPC folders do not contain the self-contained rebuild set: "
                "audio WAV/MP3 files, metadata/index.json, and metadata/container_template.bin.\n\n"
                "A folder without TXT normally falls back to unrestricted Custom Repack. "
                "You may continue as the MOD author, but CODE X may only preserve a raw container template or create an empty SPC placeholder.\n\n"
                "Continue to the final risk confirmation?\n\n" + preview,
                "一个或多个 .SPC 文件夹没有同时包含自包含重建所需的 audio WAV/MP3、metadata/index.json 和 metadata/container_template.bin。\n\n"
                "没有 TXT 的目录会正常回退到最高自由度的自定义打包。作为 MOD 作者，您仍可继续；但 CODE X 可能只能保留现有容器模板，甚至只能生成空的 SPC 占位条目。\n\n"
                "是否进入最后一次风险确认？\n\n" + preview,
            ),
            **options,
        )
        if not first:
            return False, False
        final = self._run_native_messagebox(
            messagebox.askyesno,
            self.tr("Final SPC Risk Confirmation", "SPC 最终风险确认"),
            self.tr(
                "FINAL WARNING: forced incomplete SPC content may be invalid and can make RE6 fail to load, freeze, or crash. "
                "CODE X will report every forced SPC after packing, but cannot make missing container data valid.\n\n"
                "Force these SPC folders into the custom workflow anyway?",
                "最终警告：强制使用残缺 SPC 可能生成无效内容，并导致 RE6 无法载入、卡死或闪退。CODE X 会在打包完成后列出每一个强制 SPC，但无法凭空修复缺失的容器数据。\n\n"
                "是否仍然强制让这些 SPC 文件夹进入自定义流程？",
            ),
            **options,
        )
        return bool(final), bool(final)

    def _resolve_yellow_artifacts_before_folder_input(
        self,
        parent: tk.Misc,
        artifacts: list[dict[str, Any]],
    ) -> bool:
        if not artifacts:
            return True
        paths = [
            f"YELLOW / 黄色: {item.get('relative_path', item.get('path', ''))}\n"
            f"  REQUIRED / 必须匹配: {item.get('original_relative_path', '')}"
            for item in artifacts
            if isinstance(item, dict)
        ]
        if not self._ask_batch_collision_continue(
            parent=parent,
            title_en="Yellow Intermediate Files Must Be Replaced",
            title_zh="必须替换黄色中间产物",
            message_en=(
                "Yellow LMT JSON intermediates cannot write back. Before this folder may enter the ARC tool, choose a trusted batch TXT or original ARC. CODE X will require an exact relative-path match (same directory and same .LMT filename), restore every original LMT, and remove its yellow JSON intermediates. Any missing exact match blocks the operation and leaves the folder unchanged.\n\nContinue to choose TXT/ARC?"
            ),
            message_zh=(
                "黄色的 LMT JSON 中间产物无法回写。在该文件夹进入 ARC 工具之前，必须选择可信的批量 TXT 或原始 ARC。ARC 工具会严格按完整相对路径匹配（目录一致、.LMT 文件名一致），恢复全部原始 LMT，并删除对应黄色 JSON 中间产物。任意一项无法精确匹配都会硬拦截，且不改动目录。\n\n是否继续选择 TXT/ARC？"
            ),
            collisions=paths,
        ):
            return False
        reference_text = self._ask_native_open_filename(
            title=self.tr(
                "Select Batch TXT or Original ARC",
                "选择批量 TXT 或原始 ARC",
            ),
            filetypes=[
                (self.tr("Batch TXT or RE6 ARC", "批量 TXT 或 RE6 ARC"), "*.txt *.arc"),
                (self.tr("TXT Files", "TXT 文件"), "*.txt"),
                (self.tr("RE6 ARC Files", "RE6 ARC 文件"), "*.arc"),
                (self.tr("All Files", "所有文件"), "*.*"),
            ],
            parent=parent,
        )
        if not reference_text:
            return False
        try:
            result = replace_custom_yellow_artifacts_from_reference(
                artifacts,
                Path(reference_text),
            )
        except Exception as exc:
            self.show_error(
                self.tr(
                    f"Yellow intermediate replacement failed. The folder cannot enter the ARC tool.\n\n{exc}",
                    f"黄色中间产物替换失败，文件夹不能进入 ARC 工具。\n\n{exc}",
                )
            )
            return False
        self.set_status(
            f"Restored {len(result.get('replaced_original_files', []))} original LMT files and removed {len(result.get('deleted_yellow_artifacts', []))} yellow intermediates.",
            f"已恢复 {len(result.get('replaced_original_files', []))} 个原始 LMT，并删除 {len(result.get('deleted_yellow_artifacts', []))} 个黄色中间产物。",
        )
        return True

