    def _lmt_json_export_candidates(self, source_relatives: set[str] | None) -> list[tuple[Path, str]]:
        if self.current_project_root is None:
            return []
        extract_root = conversion_workspace_extract_root(self.current_project_root, "known_formats")
        candidates: list[tuple[Path, str]] = []
        wanted = {normalize_rel_posix(item).casefold() for item in (source_relatives or set())}
        for item in load_known_parse_index(self.current_project_root).get("items", []):
            if not isinstance(item, dict) or str(item.get("parser") or "").strip().lower() != "lmt_motion":
                continue
            source_relative = normalize_rel_posix(str(item.get("source_relative_path") or "")).strip("/")
            if wanted and source_relative.casefold() not in wanted:
                continue
            for relative in item.get("parsed_files", []):
                parsed_relative = normalize_rel_posix(str(relative or "")).strip("/")
                if not parsed_relative.lower().endswith(".json"):
                    continue
                path = extract_root / Path(parsed_relative)
                if path.is_file():
                    candidates.append((path, parsed_relative))
                    break
        return candidates

    def _export_lmt_json_intermediates(
        self,
        source_relatives: set[str] | None,
        *,
        keep_structure: bool,
    ) -> None:
        candidates = self._lmt_json_export_candidates(source_relatives)
        if not candidates:
            self.show_error(self.tr("No LMT JSON intermediates were found.", "没有找到 LMT JSON 中间产物。"))
            return
        target_text = self._ask_native_directory(
            title=self.tr("Export Read-only LMT JSON", "导出只读 LMT JSON"),
            mustexist=True,
        )
        if not target_text:
            return
        export_root = Path(target_text)
        if self.current_project_root is not None:
            cache_root = runtime_cache_root_for_project(self.current_project_root)
            export_resolved = export_root.resolve()
            cache_resolved = cache_root.resolve()
            if (
                export_resolved == cache_resolved
                or export_resolved in cache_resolved.parents
                or cache_resolved in export_resolved.parents
            ):
                self.show_error(self.tr(
                    "Choose a folder outside the ARC internal cache for this explicit JSON export.",
                    "这次特批 JSON 导出必须选择 ARC 内部缓存之外的目录。",
                ))
                return
        jobs: list[tuple[Path, Path]] = []
        reserved: set[str] = set()
        for source_path, parsed_relative in candidates:
            if keep_structure:
                destination = export_root / Path(parsed_relative)
            else:
                destination = export_root / source_path.name
                index = 2
                while destination.name.casefold() in reserved or destination.exists():
                    destination = export_root / f"{source_path.stem} ({index}){source_path.suffix}"
                    index += 1
                reserved.add(destination.name.casefold())
            jobs.append((source_path, destination))

        if not self._confirm_existing_export_targets(
            [destination for _source, destination in jobs]
        ):
            return

        def task() -> dict[str, Any]:
            copied = 0
            errors: list[str] = []
            for source_path, destination in jobs:
                try:
                    ensure_parent(destination)
                    shutil.copy2(source_path, destination)
                    copied += 1
                except Exception as exc:
                    errors.append(f"{source_path}: {exc}")
            return {
                "action": "export_lmt_json_intermediates",
                "copied_count": copied,
                "errors": errors,
                "target_dir": str(export_root),
            }

        self.start_worker(self.tr("Exporting read-only LMT JSON...", "正在导出只读 LMT JSON..."), task)

    def _handle_yellow_lmt_json_export(self, side: str, metas: list[dict[str, Any]]) -> bool:
        # This easter-egg path is intentionally exact: every selected row must
        # be a known-format LMT JSON intermediate. Any mixed/normal selection
        # follows the safe export path and receives original LMT files.
        if not metas or not all(self._is_yellow_lmt_json_meta(side, meta) for meta in metas):
            return False
        action = self._ask_yellow_lmt_json_first_warning(len(metas))
        if action == "selected_gltf":
            targets = self._lmt_handoff_targets_from_metas(metas)
            self._prepare_lmt_gltf_handoff_view(
                target_sources=targets,
                scope_en=f"checked/selected LMT files ({len(targets)})",
                scope_zh=f"勾选/选中的 LMT 文件（{len(targets)}）",
            )
        elif action == "all_gltf":
            self.prepare_all_lmt_gltf_handoff_view()
        elif action == "json":
            final_choice = self._ask_yellow_lmt_json_final_export()
            if final_choice is not None:
                scope, keep_structure = final_choice
                selected_sources = {
                    normalize_rel_posix(str(meta.get("source_relative_path") or "")).strip("/")
                    for meta in metas
                }
                self._export_lmt_json_intermediates(
                    selected_sources if scope == "selected" else None,
                    keep_structure=keep_structure,
                )
        return True

    def _ask_lmt_gltf_export_options(
        self,
        project_root: Path,
        *,
        scope_en: str,
        scope_zh: str,
    ) -> dict[str, Any] | None:
        if filedialog is None or tk is None or ttk is None:
            self.show_error(self.tr("File dialog is unavailable.", "当前无法打开文件选择窗口。"))
            return None
        runtime_state = load_project_runtime_state(project_root)
        remembered = str(
            runtime_state.get("lmt_gltf_control_path")
            or runtime_state.get("lmt_gltf_control_gltf_path")
            or ""
        ).strip()
        initial_path = Path(remembered) if remembered else None
        if initial_path is not None and not initial_path.exists():
            initial_path = None

        model_count = 0
        try:
            manifest = load_project_manifest(project_root)
            model_count = sum(
                1
                for entry in manifest.get("entries", [])
                if Path(build_archive_relative_path(entry)).suffix.lower() in {".mod", ".dom"}
                and (project_root / Path(entry["extract_rel_path"])).is_file()
            )
        except Exception:
            model_count = 0

        result: dict[str, dict[str, Any] | None] = {"options": None}
        dialog = tk.Toplevel(self.root)
        dialog.title(self.tr("LMT -> GLTF/GLB Export", "LMT 转 GLTF/GLB 导出"))
        dialog.transient(self.root)
        dialog.resizable(True, False)
        dialog.minsize(940, 640)
        self._enable_dialog_workspace_reveal(dialog, show_drop_hint=True)

        remembered_auto = bool(runtime_state.get("lmt_gltf_auto_control", False))
        mode_var = tk.StringVar(value="auto" if remembered_auto else "manual")
        selected_var = tk.StringVar(value=str(initial_path) if initial_path is not None else "")
        validation_var = tk.StringVar()

        def current_path() -> Path | None:
            text = str(selected_var.get()).strip()
            return Path(text) if text else None

        def close_with(options: dict[str, Any] | None) -> None:
            result["options"] = options
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        def refresh_state(*_args: Any) -> None:
            automatic = mode_var.get() == "auto"
            selected_path = current_path()
            manual_valid = (
                selected_path is not None
                and selected_path.exists()
                and selected_path.is_file()
                and selected_path.suffix.lower() in {".mod", ".dom", ".gltf", ".glb"}
            )
            valid = model_count > 0 if automatic else manual_valid
            if automatic and model_count > 0:
                validation_var.set(
                    self.tr(
                        f"Ready. The bridge will inspect {model_count} MOD/DOM model(s) in this ARC and require a reliable match for every LMT.",
                        f"已就绪。桥接器将检查当前 ARC 中的 {model_count} 个 MOD/DOM 模型，并要求每个 LMT 都得到可靠配对。",
                    )
                )
            elif automatic:
                validation_var.set(
                    self.tr(
                        "Automatic mode needs at least one .mod or .dom model in the current ARC.",
                        "自动模式要求当前 ARC 中至少存在一个 .mod 或 .dom 模型。",
                    )
                )
            elif manual_valid:
                validation_var.set(
                    self.tr(
                        "Ready. This control model will be used for every LMT in the selected scope.",
                        "已就绪。所选控制模型将用于本次范围内的每个 LMT。",
                    )
                )
            elif selected_path is None:
                validation_var.set(
                    self.tr(
                        "Choose a MOD, DOM, GLB, or GLTF control model.",
                        "请选择 MOD、DOM、GLB 或 GLTF 控制模型。",
                    )
                )
            else:
                validation_var.set(
                    self.tr(
                        "The selected path must be an existing .mod, .dom, .glb, or .gltf file.",
                        "所选路径必须是有效的 .mod、.dom、.glb 或 .gltf 文件。",
                    )
                )
            validation_label.configure(
                foreground="#0f766e" if valid else ("#ffb454" if self.dark_mode_var.get() else "#b00020")
            )
            continue_button.configure(state="normal" if valid else "disabled")

        def choose_file() -> None:
            current = current_path()
            selected = self._ask_native_open_filename(
                title=self.tr("Choose LMT Control Model", "选择 LMT 控制模型"),
                initialdir=str(current.parent) if current is not None and current.parent.exists() else str(project_root),
                initialfile=current.name if current is not None else None,
                filetypes=[
                    (self.tr("Supported control models", "支持的控制模型"), "*.mod *.dom *.glb *.gltf"),
                    ("RE6 MOD / DOM", "*.mod *.dom"),
                    (self.tr("glTF / GLB", "glTF / GLB"), "*.glb *.gltf"),
                    ("MOD", "*.mod"),
                    ("DOM", "*.dom"),
                    ("GLB", "*.glb"),
                    ("glTF", "*.gltf"),
                    (self.tr("All files", "所有文件"), "*.*"),
                ],
                parent=dialog,
            )
            if selected:
                mode_var.set("manual")
                selected_var.set(str(Path(selected)))

        def confirm_selection() -> None:
            refresh_state()
            automatic = mode_var.get() == "auto"
            selected_path = current_path()
            if continue_button.cget("state") == "disabled":
                return
            if automatic:
                self._update_project_runtime_state(lmt_gltf_auto_control=True)
                close_with({"auto_control": True})
                return
            if selected_path is None:
                return
            self._update_project_runtime_state(
                lmt_gltf_auto_control=False,
                lmt_gltf_control_path=str(selected_path),
                lmt_gltf_control_gltf_path=str(selected_path),
            )
            close_with({"auto_control": False, "control_path": str(selected_path)})

        body = ttk.Frame(dialog, padding=16)
        body.pack(fill="both", expand=True)
        body.columnconfigure(0, weight=1)

        ttk.Label(
            body,
            text=self.tr(
                f"Conversion scope: {scope_en}",
                f"本次转换范围：{scope_zh}",
            ),
            justify="left",
        ).grid(row=0, column=0, sticky="w")

        mode_frame = ttk.LabelFrame(
            body,
            text=self.tr("Control Model Mode", "控制模型模式"),
            padding=12,
        )
        mode_frame.grid(row=1, column=0, sticky="ew", pady=(12, 0))
        ttk.Radiobutton(
            mode_frame,
            text=self.tr(
                "Choose one MOD / DOM / GLB / GLTF control model",
                "手动选择一个 MOD / DOM / GLB / GLTF 控制模型",
            ),
            variable=mode_var,
            value="manual",
        ).pack(anchor="w")
